import os, pty, subprocess, select, time, sys, json
def interact(name, args, sends):
    print(f"\n===== {name} args={args} sends={sends} =====")
    pid, fd = pty.fork()
    if pid==0:
        os.chdir("/tmp/probe")
        os.execv("/workspace/executable", ["/workspace/executable"]+args)
    raw=b""
    sends=list(sends)
    exitcode=None
    start=time.time()
    last_activity=time.time()
    while time.time()-start<15:
        r,_,_=select.select([fd],[],[],0.2)
        if r:
            try: chunk=os.read(fd, 4096)
            except OSError: break
            if not chunk: break
            raw+=chunk; last_activity=time.time()
            # If prompt awaiting input: heuristic wait 0.3 and send if latest chunk contains ':' or '?'
        # if no data recently and sends remain, send next
        if sends and time.time()-last_activity>0.3:
            s=sends.pop(0)
            raw+=f"<<SEND:{s!r}>>".encode()
            # Ctrl-C etc are sent as bytes
            try: os.write(fd, s)
            except OSError: break
            last_activity=time.time()
        # check exit
        try:
            wpid,status=os.waitpid(pid, os.WNOHANG)
        except ChildProcessError:
            break
        if wpid==pid:
            exitcode=os.waitstatus_to_exitcode(status); break
    if exitcode is None:
        try:
            os.kill(pid,9); _,status=os.waitpid(pid,0); exitcode=f"killed/timeout {os.waitstatus_to_exitcode(status)}"
        except Exception as e: exitcode=str(e)
    print("EXIT",exitcode)
    print("RAW",repr(raw))
    return raw,exitcode
if __name__=="__main__":
    import pathlib
    pathlib.Path("/tmp/probe/plain.txt").write_text("hello passphrase\n")
    cases=eval(sys.argv[1]) if len(sys.argv)>1 else []
    for name,args,sends in cases:
        # sends are strings latin1 decoded? encode via unicode_escape
        bs=[bytes(s,'utf-8').decode('unicode_escape').encode('latin1') if isinstance(s,str) else s for s in sends]
        interact(name,args,bs)
