#!/usr/bin/env python3
import sys
log=open('/tmp/probe/plugin.log','ab')
def L(x): log.write((str(x)+"\n").encode()); log.flush()
L(f"=== argv={sys.argv!r}")
current=None; filekey=None; stanza_body=None; keys={}
while True:
    line=sys.stdin.buffer.readline()
    if not line:
        L("EOF"); sys.exit(0)
    L(f"IN {line!r}")
    s=line.strip()
    if s.startswith(b"-> "):
        parts=s.split(b" ")
        current=parts[1].decode()
        if current=="done":
            body=sys.stdin.buffer.readline(); L(f"done body {body!r}")
            break
    else:
        if current=="wrap-file-key" and s: filekey=s.decode()
        if current=="recipient-stanza" and s: stanza_body=s.decode()
if "--age-plugin=recipient-v1" in sys.argv:
    resp=f"-> recipient-stanza 0 example testarg\n{filekey}\n-> done\n\n"
else:
    resp=f"-> file-key 0\n{stanza_body}\n-> done\n\n"
L(f"OUT {resp!r}")
sys.stdout.write(resp); sys.stdout.flush()
while True:
    line=sys.stdin.buffer.readline(); L(f"AFTER {line!r}")
    if not line: break
L("END EOF")
