#!/usr/bin/env python3
import sys, os
log=open('/tmp/probe/plugin.log','ab')
def L(x): log.write((str(x)+"\n").encode()); log.flush()
# helper parse stanzas until done
def read_phase():
    stanzas=[]
    cur=None
    while True:
        line=sys.stdin.buffer.readline()
        L(f"IN {line!r}")
        if not line:
            return None
        s=line.rstrip(b'\n')
        if s.startswith(b'-> '):
            cur=[s,[]]; stanzas.append(cur)
            if s.split(b' ')[1]==b'done':
                # body line(s): done body expected blank, read one line
                body=sys.stdin.buffer.readline(); L(f"IN donebody {body!r}")
                if body.strip(): cur[1].append(body.strip())
                return stanzas
            if s.split(b' ')[1]==b'ok':
                # ok has empty body blank
                body=sys.stdin.buffer.readline(); L(f"IN okbody {body!r}")
                return stanzas
        else:
            if cur is not None and s: cur[1].append(s)
def send(text):
    L(f"OUT {text!r}")
    if isinstance(text,str): text=text.encode()
    sys.stdout.buffer.write(text); sys.stdout.buffer.flush()
L(f"argv={sys.argv}")
phase1=read_phase(); L(f"phase1 {phase1}")
fk=None
for hdr,body in phase1 or []:
    if hdr.startswith(b'-> wrap-file-key'): fk=b''.join(body).decode()
# initial response from env file /tmp/probe/plugin_response.txt
with open('/tmp/probe/plugin_response.txt','rb') as f: resp=f.read()
send(resp)
phase2=read_phase(); L(f"phase2 {phase2}")
if phase2 is None: sys.exit(0)
# if phase2 is ok (means our response completed operation) just exit after EOF in read_phase? Actually ok ends read_phase, then client closes, next read None.
# If phase2 contains response etc and ends done, complete with recipient stanza
if any(h.startswith(b'-> ok') for h,b in phase2):
    nxt=read_phase(); L(f"after ok {nxt}"); sys.exit(0)
# second response from env if exists
try:
    with open('/tmp/probe/plugin_response2.txt','rb') as f: resp2=f.read()
except:
    resp2=f"-> recipient-stanza 0 example testarg\n{fk}\n-> done\n\n".encode()
send(resp2)
phase3=read_phase(); L(f"phase3 {phase3}")
EOS
