samples=[]
for s in D['samples']:
    samples.append({k:bytes.fromhex(v) for k,v in s.items()})
def hkdf_extract(salt,ikm,hashfn=hashlib.sha256):
    return hmac.new(salt if salt else b'\x00'*hashfn().digest_size,ikm,hashfn).digest()
def hkdf_expand(prk,info,L,hashfn=hashlib.sha256):
    out=b'';t=b'';i=1
    while len(out)<L:
        t=hmac.new(prk,t+info+bytes([i]),hashfn).digest();out+=t;i+=1
    return out[:L]
def hkdf(ikm,salt,info,L): return hkdf_expand(hkdf_extract(salt,ikm),info,L)
def lext(suite,salt,label,ikm): return hkdf_extract(salt,b'HPKE-v1'+suite+label+ikm)
def lexp(suite,prk,label,info,L): return hkdf_expand(prk,L.to_bytes(2,'big')+b'HPKE-v1'+suite+label+info,L)
def dhkem_ss(kem_id,dh,enc,pk_):
    suite=b'KEM'+kem_id.to_bytes(2,'big')
    prk=lext(suite,b'',b'eae_prk',dh)
    return lexp(suite,prk,b'shared_secret',enc+pk_,32)
def hpke_key_nonce(kem_id,ss,info,aead_id=3,Nk=32):
    suite=b'HPKE'+kem_id.to_bytes(2,'big')+(1).to_bytes(2,'big')+aead_id.to_bytes(2,'big')
    pskh=lext(suite,b'',b'psk_id_hash',b''); ih=lext(suite,b'',b'info_hash',info); ctx=b'\x00'+pskh+ih
    secret=lext(suite,ss,b'secret',b'')
    return lexp(suite,secret,b'key',ctx,Nk), lexp(suite,secret,b'base_nonce',ctx,12)
def combined_candidates(s):
    ssM=s['ssM']; dh=s['dhX']; enc=s['enc']; eph=s['eph']; ct=s['ct']
    ssX=dhkem_ss(0x20,dh,eph,pkX)
    out={}
    out['ssM+dh']=ssM+dh; out['dh+ssM']=dh+ssM; out['ssM+ssX']=ssM+ssX; out['ssX+ssM']=ssX+ssM; out['ssM']=ssM; out['dh']=dh; out['ssX']=ssX; out['xwing']=s['xwing']; out['sha256_ml_dh']=s['sha256_ml_dh']; out['sha256_dh_ml']=s['sha256_dh_ml']; out['sha3_ml_dh']=s['sha3_ml_dh']
    # XWing variants with ssX dhkem rather than dh
    out['xwing_ssX']=hashlib.sha3_256(ssM+ssX+eph+pkX+b"\\.^//").digest()
    out['xwing_sha256']=hashlib.sha256(ssM+dh+eph+pkX+b"\\.^//").digest()
    # hybrid extract&expand candidate for a list later handled separately (kem suite varies)
    return out
infos=[b'',b'age-encryption.org/v1/mlkem768x25519',b'mlkem768x25519',b'age-encryption.org/v1/MLKEM768-X25519',b'age-encryption.org/v1/mlkem768-x25519']
kem_ids=[0x647a,0x6430,0x0041,0x0040,0x0042,0x0020,0x0010,0x0001,0x004d,0x0050,0x0060,0x6470,0x6460,0x6600]
found=[]
# first candidate combined raw/xwing etc into HPKE schedule
for kem_id in kem_ids:
 for info in infos:
  for aadname in ['empty','enc']:
   cand_names=list(combined_candidates(samples[0]).keys())
   for cname in cand_names:
    ok=True; vals=[]
    for s in samples:
        ss=combined_candidates(s)[cname]
        key,nonce=hpke_key_nonce(kem_id,ss,info,3,32)
        aad=b'' if aadname=='empty' else s['enc']
        try: vals.append(aead_decrypt(key,nonce,s['wrapped'],aad))
        except: ok=False;break
    if ok: print("MATCH HPKE ChaCha rawcomb",hex(kem_id),info,aadname,cname,vals); found.append(1)
print("phase raw done",found)
# Hybrid E&E combined SS, kem ids same for combine and schedule
for kem_id in kem_ids:
 for info in infos:
  for combo_name in ['ssM+dh','dh+ssM','ssM+ssX','ssX+ssM']:
   for ctxname in ['enc+pk','pk+enc','encM+encX+pkM+pkX','encX+pkX + ctM+pkM']:
    ok=True;vals=[]
    for s in samples:
        cc=combined_candidates(s); ikm=cc[combo_name]
        suite=b'KEM'+kem_id.to_bytes(2,'big')
        if ctxname=='enc+pk': ctx=s['enc']+pk
        elif ctxname=='pk+enc': ctx=pk+s['enc']
        elif ctxname=='encM+encX+pkM+pkX': ctx=s['ct']+s['eph']+pkM+pkX
        else: ctx=s['eph']+pkX+s['ct']+pkM
        prk=lext(suite,b'',b'eae_prk',ikm); ss=lexp(suite,prk,b'shared_secret',ctx,32)
        key,nonce=hpke_key_nonce(kem_id,ss,info,3,32)
        try: vals.append(aead_decrypt(key,nonce,s['wrapped']))
        except: ok=False;break
    if ok: print("MATCH HPKE ChaCha hybridEE",hex(kem_id),info,combo_name,ctxname,vals);found.append(1)
print("done",found)
