func bruteHybrid(in In) {
	infos := [][]byte{[]byte("age-encryption.org/v1/mlkem768x25519"), []byte(""), []byte("mlkem768x25519")}
	comboNames := []string{"ssM+dh", "dh+ssM", "ssM+ssX", "ssX+ssM"}
	for kem := 0; kem < 65536; kem++ {
		if kem%8192 == 0 { fmt.Println("hybrid kem", kem) }
		suite := []byte{'K', 'E', 'M', byte(kem >> 8), byte(kem)}
		for ii, info := range infos {
			for _, cname := range comboNames {
				for ctxi := 0; ctxi < 3; ctxi++ {
					for _, aead := range []int{3, 1, 2} {
						Nk := 32
						if aead == 1 { Nk = 16 }
						s := in.Samples[0]
						ikm := combos(s)[cname]
						var ctx []byte
						if ctxi == 0 { ctx = append(append([]byte{}, hx(s["enc"])...), pk...) }
						if ctxi == 1 { ctx = append(append([]byte{}, pk...), hx(s["enc"])...) }
						if ctxi == 2 { // ctM+ephX+pkM+pkX same as enc+pk actually (enc is that, pk that) - alternative: separate KEM contexts eph+pkX+ct+pkM
							ctx = append(append(append(append([]byte{}, hx(s["eph"])...), pkX...), hx(s["ct"])...), pkM...)
						}
						prk := lext(suite, nil, "eae_prk", ikm)
						ss := lexp(suite, prk, "shared_secret", ctx, 32)
						key, nonce := hpkeKN(kem, aead, Nk, ss, info)
						var pt []byte
						var ok bool
						if aead == 3 { pt, ok = tryChaCha(key, nonce, hx(s["wrapped"]), nil) } else { pt, ok = tryAES(key, nonce, hx(s["wrapped"]), nil) }
						if ok { fmt.Printf("HYBRID CANDIDATE kem=%04x info%d=%q combo=%s ctx=%d aead=%d pt=%x\n", kem, ii, info, cname, ctxi, aead, pt) }
					}
				}
			}
		}
	}
	fmt.Println("hybrid brute done")
}
