  bytesOpt{"pkM",func(map[string]string)[]byte{return pkM}},
  bytesOpt{"pkX",func(map[string]string)[]byte{return pkX}},
  bytesOpt{"enc",func(s map[string]string)[]byte{return hx(s["enc"])}},
  bytesOpt{"eph",func(s map[string]string)[]byte{return hx(s["eph"])}},
