package main

import (
	"errors"
	"fmt"
	"strings"
)

const bech32Charset = "qpzry9x8gf2tvdw0s3jn54khce6mua7l"

var bech32Rev [128]int8

func init() {
	for i := range bech32Rev {
		bech32Rev[i] = -1
	}
	for i, c := range bech32Charset {
		bech32Rev[c] = int8(i)
	}
}

func bech32Polymod(values []byte) uint32 {
	gen := []uint32{0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3}
	chk := uint32(1)
	for _, v := range values {
		b := chk >> 25
		chk = ((chk & 0x1ffffff) << 5) ^ uint32(v)
		for i := 0; i < 5; i++ {
			if (b>>uint(i))&1 == 1 {
				chk ^= gen[i]
			}
		}
	}
	return chk
}

func bech32HRPExpand(hrp string) []byte {
	out := make([]byte, 0, len(hrp)*2+1)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]>>5)
	}
	out = append(out, 0)
	for i := 0; i < len(hrp); i++ {
		out = append(out, hrp[i]&31)
	}
	return out
}

func bech32CreateChecksum(hrp string, data []byte) []byte {
	values := append(bech32HRPExpand(hrp), data...)
	values = append(values, 0, 0, 0, 0, 0, 0)
	polymod := bech32Polymod(values) ^ 1
	out := make([]byte, 6)
	for i := 0; i < 6; i++ {
		out[i] = byte((polymod >> uint(5*(5-i))) & 31)
	}
	return out
}

func bech32ConvertBits(data []byte, fromBits, toBits uint, pad bool) ([]byte, error) {
	var acc uint32
	var bits uint
	out := make([]byte, 0, len(data)*int(fromBits)/int(toBits)+1)
	maxv := uint32((1 << toBits) - 1)
	maxAcc := uint32((1 << (fromBits + toBits - 1)) - 1)
	for _, v := range data {
		if uint32(v)>>(fromBits) != 0 {
			return nil, errors.New("invalid data range")
		}
		acc = ((acc << fromBits) | uint32(v)) & maxAcc
		bits += fromBits
		for bits >= toBits {
			bits -= toBits
			out = append(out, byte((acc>>bits)&maxv))
		}
	}
	if pad {
		if bits > 0 {
			out = append(out, byte((acc<<(toBits-bits))&maxv))
		}
	} else if bits >= fromBits || ((acc<<(toBits-bits))&maxv) != 0 {
		return nil, errors.New("invalid padding")
	}
	return out, nil
}

func bech32Encode(hrp string, data []byte) (string, error) {
	converted, err := bech32ConvertBits(data, 8, 5, true)
	if err != nil {
		return "", err
	}
	combined := append(converted, bech32CreateChecksum(hrp, converted)...)
	var sb strings.Builder
	sb.WriteString(hrp)
	sb.WriteByte('1')
	for _, b := range combined {
		sb.WriteByte(bech32Charset[b])
	}
	return sb.String(), nil
}

func bech32EncodeUpper(hrp string, data []byte) (string, error) {
	s, err := bech32Encode(strings.ToLower(hrp), data)
	if err != nil {
		return "", err
	}
	return strings.ToUpper(s), nil
}

// bech32Decode returns the lower-cased HRP and the decoded data bytes.
// Error strings intentionally match the observable messages produced by the
// reference tool for malformed encodings.
func bech32Decode(s string) (string, []byte, error) {
	if strings.ToLower(s) != s && strings.ToUpper(s) != s {
		return "", nil, errors.New("mixed case")
	}
	pos := strings.LastIndexByte(s, '1')
	if pos < 1 || pos+7 > len(s) {
		return "", nil, fmt.Errorf("separator '1' at invalid position: pos=%d, len=%d", pos, len(s))
	}
	hrp := strings.ToLower(s[:pos])
	for i := 0; i < len(hrp); i++ {
		if hrp[i] < 33 || hrp[i] > 126 {
			return "", nil, fmt.Errorf("invalid character human-readable part: s[%d]=%d", i, hrp[i])
		}
	}
	dataPart := strings.ToLower(s[pos+1:])
	data := make([]byte, len(dataPart))
	for i := 0; i < len(dataPart); i++ {
		c := dataPart[i]
		if c > 127 || bech32Rev[c] < 0 {
			return "", nil, fmt.Errorf("invalid character data part: s[%d]=%d", i, c)
		}
		data[i] = byte(bech32Rev[c])
	}
	values := append(bech32HRPExpand(hrp), data...)
	if bech32Polymod(values) != 1 {
		return "", nil, errors.New("invalid checksum")
	}
	converted, err := bech32ConvertBits(data[:len(data)-6], 5, 8, false)
	if err != nil {
		return "", nil, err
	}
	return hrp, converted, nil
}
