package main

import (
	"encoding/binary"
	"errors"
	"math/bits"
)

func chachaQuarter(x []uint32, a, b, c, d int) {
	x[a] += x[b]
	x[d] = bits.RotateLeft32(x[d]^x[a], 16)
	x[c] += x[d]
	x[b] = bits.RotateLeft32(x[b]^x[c], 12)
	x[a] += x[b]
	x[d] = bits.RotateLeft32(x[d]^x[a], 8)
	x[c] += x[d]
	x[b] = bits.RotateLeft32(x[b]^x[c], 7)
}

func chachaBlock(key []byte, counter uint32, nonce []byte) [64]byte {
	var state [16]uint32
	constants := "expand 32-byte k"
	for i := 0; i < 4; i++ {
		state[i] = binary.LittleEndian.Uint32([]byte(constants[i*4:(i+1)*4]))
	}
	for i := 0; i < 8; i++ {
		state[4+i] = binary.LittleEndian.Uint32(key[i*4 : (i+1)*4])
	}
	state[12] = counter
	for i := 0; i < 3; i++ {
		state[13+i] = binary.LittleEndian.Uint32(nonce[i*4 : (i+1)*4])
	}
	x := state
	for i := 0; i < 10; i++ {
		chachaQuarter(x[:], 0, 4, 8, 12)
		chachaQuarter(x[:], 1, 5, 9, 13)
		chachaQuarter(x[:], 2, 6, 10, 14)
		chachaQuarter(x[:], 3, 7, 11, 15)
		chachaQuarter(x[:], 0, 5, 10, 15)
		chachaQuarter(x[:], 1, 6, 11, 12)
		chachaQuarter(x[:], 2, 7, 8, 13)
		chachaQuarter(x[:], 3, 4, 9, 14)
	}
	var out [64]byte
	for i := 0; i < 16; i++ {
		binary.LittleEndian.PutUint32(out[i*4:(i+1)*4], x[i]+state[i])
	}
	return out
}

func hchacha(key, nonce []byte) []byte {
	var state [16]uint32
	constants := "expand 32-byte k"
	for i := 0; i < 4; i++ {
		state[i] = binary.LittleEndian.Uint32([]byte(constants[i*4:(i+1)*4]))
	}
	for i := 0; i < 8; i++ {
		state[4+i] = binary.LittleEndian.Uint32(key[i*4 : (i+1)*4])
	}
	for i := 0; i < 4; i++ {
		state[12+i] = binary.LittleEndian.Uint32(nonce[i*4 : (i+1)*4])
	}
	x := state
	for i := 0; i < 10; i++ {
		chachaQuarter(x[:], 0, 4, 8, 12)
		chachaQuarter(x[:], 1, 5, 9, 13)
		chachaQuarter(x[:], 2, 6, 10, 14)
		chachaQuarter(x[:], 3, 7, 11, 15)
		chachaQuarter(x[:], 0, 5, 10, 15)
		chachaQuarter(x[:], 1, 6, 11, 12)
		chachaQuarter(x[:], 2, 7, 8, 13)
		chachaQuarter(x[:], 3, 4, 9, 14)
	}
	out := make([]byte, 32)
	for i, idx := range []int{0, 1, 2, 3, 12, 13, 14, 15} {
		binary.LittleEndian.PutUint32(out[i*4:(i+1)*4], x[idx])
	}
