}

func chachaStream(key []byte, counter uint32, nonce, in []byte) []byte {
	out := make([]byte, len(in))
	for i := 0; i < len(in); i += 64 {
		block := chachaBlock(key, counter, nonce)
		counter++
		for j := 0; j < 64 && i+j < len(in); j++ {
			out[i+j] = in[i+j] ^ block[j]
		}
	}
	return out
}

// poly1305 implements RFC 8439 Poly1305 with 26-bit limbs.
type poly1305State struct {
	r [5]uint64
	h [5]uint64
	s [4]uint64 // not used as limbs; raw words for final addition below
}

func load32LE(b []byte) uint64 { return uint64(binary.LittleEndian.Uint32(b)) }

func poly1305MAC(msg, key []byte) [16]byte {
	// This implementation uses the classic 5x26-bit representation.
	var st poly1305State
	// r = le_bytes(key[0:16]) & 0x0ffffffc0ffffffc0ffffffc0fffffff
	t0 := load32LE(key[0:4])
	t1 := load32LE(key[4:8])
	t2 := load32LE(key[8:12])
	t3 := load32LE(key[12:16])
	st.r[0] = t0 & 0x3ffffff
	st.r[1] = ((t0 >> 26) | (t1 << 6)) & 0x3ffff03
	st.r[2] = ((t1 >> 20) | (t2 << 12)) & 0x3ffc0ff
	st.r[3] = ((t2 >> 14) | (t3 << 18)) & 0x3f03fff
	st.r[4] = (t3 >> 8) & 0x00fffff
	// Precompute 5*r[1..4] in separate variables during multiplication.

	for len(msg) > 0 {
		var block [16]byte
		n := copy(block[:], msg)
		msg = msg[n:]
		hib := uint64(1) << 24
		if n < 16 {
			block[n] = 1
			for i := n + 1; i < 16; i++ {
				block[i] = 0
			}
			hib = 0
		}
		b0 := load32LE(block[0:4])
		b1 := load32LE(block[4:8])
		b2 := load32LE(block[8:12])
		b3 := load32LE(block[12:16])
		st.h[0] += b0 & 0x3ffffff
		st.h[1] += ((b0 >> 26) | (b1 << 6)) & 0x3ffffff
		st.h[2] += ((b1 >> 20) | (b2 << 12)) & 0x3ffffff
		st.h[3] += ((b2 >> 14) | (b3 << 18)) & 0x3ffffff
		st.h[4] += (b3 >> 8) | hib

		r := st.r
		s1, s2, s3, s4 := r[1]*5, r[2]*5, r[3]*5, r[4]*5
		h := st.h
		d0 := h[0]*r[0] + h[1]*s4 + h[2]*s3 + h[3]*s2 + h[4]*s1
		d1 := h[0]*r[1] + h[1]*r[0] + h[2]*s4 + h[3]*s3 + h[4]*s2
		d2 := h[0]*r[2] + h[1]*r[1] + h[2]*r[0] + h[3]*s4 + h[4]*s3
		d3 := h[0]*r[3] + h[1]*r[2] + h[2]*r[1] + h[3]*r[0] + h[4]*s4
		d4 := h[0]*r[4] + h[1]*r[3] + h[2]*r[2] + h[3]*r[1] + h[4]*r[0]
