		c = d0 >> 26
		h[0] = d0 & 0x3ffffff
		d1 += c
		c = d1 >> 26
		h[1] = d1 & 0x3ffffff
		d2 += c
		c = d2 >> 26
		h[2] = d2 & 0x3ffffff
		d3 += c
		c = d3 >> 26
		h[3] = d3 & 0x3ffffff
		d4 += c
		c = d4 >> 26
		h[4] = d4 & 0x3ffffff
		h[0] += c * 5
		c = h[0] >> 26
		h[0] &= 0x3ffffff
		h[1] += c
		st.h = h
	}
	h := st.h
	// Full carry.
	var c uint64
	c = h[1] >> 26
	h[1] &= 0x3ffffff
	h[2] += c
	c = h[2] >> 26
	h[2] &= 0x3ffffff
	h[3] += c
	c = h[3] >> 26
	h[3] &= 0x3ffffff
	h[4] += c
	c = h[4] >> 26
	h[4] &= 0x3ffffff
	h[0] += c * 5
	c = h[0] >> 26
	h[0] &= 0x3ffffff
	h[1] += c
	// Compute h + -p, select h if h < p else h+ -p.
	g0 := h[0] + 5
	c = g0 >> 26
	g0 &= 0x3ffffff
	g1 := h[1] + c
	c = g1 >> 26
	g1 &= 0x3ffffff
	g2 := h[2] + c
	c = g2 >> 26
	g2 &= 0x3ffffff
	g3 := h[3] + c
	c = g3 >> 26
	g3 &= 0x3ffffff
