	mask := uint64(int64(g4) >> 63) // 0 if g4>=0 (h>=p?) careful: g4 is unsigned wrap if negative
	// The above is unreliable for wrapped values, so determine with a
	// straightforward comparison of h against p in 26-bit limbs.
	// p = 2^130-5 limbs: [0x3fffffb, 0x3ffffff, 0x3ffffff, 0x3ffffff, 0x3ffffff]
	_ = mask
	ge := true
	pLimbs := [5]uint64{0x3fffffb, 0x3ffffff, 0x3ffffff, 0x3ffffff, 0x3ffffff}
	for i := 4; i >= 0; i-- {
		if h[i] < pLimbs[i] {
			ge = false
			break
		} else if h[i] > pLimbs[i] {
			ge = true
			break
		}
	}
	if ge {
		h[0], h[1], h[2], h[3], h[4] = g0, g1, g2, g3, g4
	}
	// Serialize h to 128-bit little endian (h mod 2^128) and add s.
	h0 := h[0] | (h[1] << 26)
	h1 := (h[1] >> 6) | (h[2] << 20)
	h2 := (h[2] >> 12) | (h[3] << 14)
	h3 := (h[3] >> 18) | (h[4] << 8)
	s0 := load32LE(key[16:20])
	s1 := load32LE(key[20:24])
	s2 := load32LE(key[24:28])
	s3 := load32LE(key[28:32])
	h0 += s0
	h1 += s1 + (h0 >> 32)
	h0 &= 0xffffffff
	h2 += s2 + (h1 >> 32)
	h1 &= 0xffffffff
	h3 += s3 + (h2 >> 32)
	h2 &= 0xffffffff
	h3 &= 0xffffffff
	var out [16]byte
	binary.LittleEndian.PutUint32(out[0:4], uint32(h0))
	binary.LittleEndian.PutUint32(out[4:8], uint32(h1))
	binary.LittleEndian.PutUint32(out[8:12], uint32(h2))
	binary.LittleEndian.PutUint32(out[12:16], uint32(h3))
	return out
}

func pad16Len(n int) int {
	if n%16 == 0 {
		return 0
	}
	return 16 - n%16
}

func chachaPoly1305Seal(key, nonce, plaintext, aad []byte) []byte {
	if len(nonce) == 24 {
		subkey := hchacha(key, nonce[:16])
		nonce12 := append([]byte{0, 0, 0, 0}, nonce[16:24]...)
		return chachaPoly1305Seal(subkey, nonce12, plaintext, aad)
	}
	otkBlock := chachaBlock(key, 0, nonce)
	otk := otkBlock[:32]
	ciphertext := chachaStream(key, 1, nonce, plaintext)
	macData := make([]byte, 0, len(aad)+pad16Len(len(aad))+len(ciphertext)+pad16Len(len(ciphertext))+16)
	macData = append(macData, aad...)
	macData = append(macData, make([]byte, pad16Len(len(aad)))...)
	macData = append(macData, ciphertext...)
	macData = append(macData, make([]byte, pad16Len(len(ciphertext)))...)
	var lens [16]byte
	binary.LittleEndian.PutUint64(lens[0:8], uint64(len(aad)))
	binary.LittleEndian.PutUint64(lens[8:16], uint64(len(ciphertext)))
	macData = append(macData, lens[:]...)
	tag := poly1305MAC(macData, otk)
	return append(ciphertext, tag[:]...)
}

var errAEAD = errors.New("chacha20poly1305: message authentication failed")

func chachaPoly1305Open(key, nonce, ciphertext, aad []byte) ([]byte, error) {
	if len(nonce) == 24 {
		subkey := hchacha(key, nonce[:16])
		nonce12 := append([]byte{0, 0, 0, 0}, nonce[16:24]...)
		return chachaPoly1305Open(subkey, nonce12, ciphertext, aad)
	}
	if len(ciphertext) < 16 {
		return nil, errAEAD
	}
	ct := ciphertext[:len(ciphertext)-16]
	tag := ciphertext[len(ciphertext)-16:]
	otkBlock := chachaBlock(key, 0, nonce)
	otk := otkBlock[:32]
	macData := make([]byte, 0, len(aad)+pad16Len(len(aad))+len(ct)+pad16Len(len(ct))+16)
	macData = append(macData, aad...)
	macData = append(macData, make([]byte, pad16Len(len(aad)))...)
	macData = append(macData, ct...)
	macData = append(macData, make([]byte, pad16Len(len(ct)))...)
	var lens [16]byte
	binary.LittleEndian.PutUint64(lens[0:8], uint64(len(aad)))
	binary.LittleEndian.PutUint64(lens[8:16], uint64(len(ct)))
	macData = append(macData, lens[:]...)
	expected := poly1305MAC(macData, otk)
	var diff byte
	for i := 0; i < 16; i++ {
		diff |= expected[i] ^ tag[i]
	}
	if diff != 0 {
		return nil, errAEAD
	}
	return chachaStream(key, 1, nonce, ct), nil
}
