package main

import (
	"crypto/hmac"
	"crypto/sha256"
	"hash"
)

func hkdfSHA256(ikm, salt, info []byte, length int) []byte {
	return hkdf(sha256.New, ikm, salt, info, length)
}

func hkdf(h func() hash.Hash, ikm, salt, info []byte, length int) []byte {
	prk := hkdfExtract(h, salt, ikm)
	return hkdfExpand(h, prk, info, length)
}

func hkdfExtract(h func() hash.Hash, salt, ikm []byte) []byte {
	if salt == nil {
		salt = make([]byte, h().Size())
	}
	m := hmac.New(h, salt)
	m.Write(ikm)
	return m.Sum(nil)
}

func hkdfExpand(h func() hash.Hash, prk, info []byte, length int) []byte {
	var out, t []byte
	for counter := byte(1); len(out) < length; counter++ {
		m := hmac.New(h, prk)
		m.Write(t)
		m.Write(info)
		m.Write([]byte{counter})
		t = m.Sum(nil)
		out = append(out, t...)
	}
	return out[:length]
}
