		if h[i] < pLimbs[i] {
			ge = false
			break
		} else if h[i] > pLimbs[i] {
			ge = true
			break
		}
	}
	if ge {
		h[0], h[1], h[2], h[3], h[4] = g0, g1, g2, g3, g4
	}
	// Serialize h to 128-bit little endian (h mod 2^128) and add s.
	h0 := h[0] | (h[1] << 26)
	h1 := (h[1] >> 6) | (h[2] << 20)
	h2 := (h[2] >> 12) | (h[3] << 14)
	h3 := (h[3] >> 18) | (h[4] << 8)
