				a[idx] = b[idx] ^ (^b[(x+1)%5+5*y] & b[(x+2)%5+5*y])
			}
		}
		a[0] ^= rc
	}
}

func keccak(rate int, suffix byte, data []byte, outLen int) []byte {
	var state [25]uint64
	for len(data) >= rate {
		for i := 0; i < rate/8; i++ {
			state[i] ^= binary.LittleEndian.Uint64(data[i*8 : (i+1)*8])
		}
		// rate is always a multiple of 8 for parameters used here.
		keccakF1600(&state)
		data = data[rate:]
	}
	var block [200]byte
	copy(block[:], data)
	block[len(data)] = suffix
	block[rate-1] |= 0x80
	for i := 0; i < rate/8; i++ {
		state[i] ^= binary.LittleEndian.Uint64(block[i*8 : (i+1)*8])
	}
	keccakF1600(&state)
	out := make([]byte, 0, outLen)
	for len(out) < outLen {
		for i := 0; i < rate/8 && len(out) < outLen; i++ {
			var tmp [8]byte
			binary.LittleEndian.PutUint64(tmp[:], state[i])
			out = append(out, tmp[:]...)
		}
		if len(out) < outLen {
			keccakF1600(&state)
		}
	}
	return out[:outLen]
}

func sha3_256(data []byte) []byte { return keccak(136, 0x06, data, 32) }
func sha3_512(data []byte) []byte { return keccak(72, 0x06, data, 64) }
func shake128(data []byte, outLen int) []byte { return keccak(168, 0x1f, data, outLen) }
func shake256(data []byte, outLen int) []byte { return keccak(136, 0x1f, data, outLen) }
EOF
