	}
	mu := mlkemDecompress(1, mlkemByteDecode(1, m))
	var acc mlkemPoly
	for j := 0; j < mlkemK; j++ {
		acc = mlkemAdd(acc, mlkemMultiplyNTT(th[j], yh[j]))
	}
	v := mlkemAdd(mlkemAdd(mlkemINTT(acc), e2), mu)
	ct = append(ct, mlkemByteEncode(mlkemDV, mlkemCompress(mlkemDV, v))...)
	return ct
}

func mlkemKPKEDecrypt(dk, ct []byte) []byte {
	c1 := ct[:32*mlkemDU*mlkemK]
	c2 := ct[32*mlkemDU*mlkemK:]
	v := mlkemDecompress(mlkemDV, mlkemByteDecode(mlkemDV, c2))
	var acc mlkemPoly
	for i := 0; i < mlkemK; i++ {
		u := mlkemDecompress(mlkemDU, mlkemByteDecode(mlkemDU, c1[i*32*mlkemDU:(i+1)*32*mlkemDU]))
		sh := mlkemByteDecode(12, dk[i*polySize384:(i+1)*polySize384])
		acc = mlkemAdd(acc, mlkemMultiplyNTT(sh, mlkemNTT(u)))
	}
	w := mlkemSub(v, mlkemINTT(acc))
	return mlkemByteEncode(1, mlkemCompress(1, w))
}

func mlkemKeyGenFromSeed(seed []byte) (ek, dk []byte) {
	// seed is d || z, 32 bytes each.
	ek, dkPKE := mlkemKPKEKeyGen(seed[:32])
	dk = append([]byte(nil), dkPKE...)
	dk = append(dk, ek...)
	dk = append(dk, sha3_256(ek)...)
	dk = append(dk, seed[32:64]...)
	return ek, dk
}

func mlkemEncapsulate(ek []byte) (shared, ct []byte, err error) {
	m := make([]byte, 32)
	if _, err := rand.Read(m); err != nil {
		return nil, nil, err
	}
	g := sha3_512(append(append([]byte(nil), m...), sha3_256(ek)...))
	ct = mlkemKPKEEncrypt(ek, m, g[32:])
	return g[:32], ct, nil
}

func mlkemDecapsulate(dk, ct []byte) ([]byte, error) {
	if len(dk) != mlkemDKSize || len(ct) != mlkemCTSize {
		return nil, errors.New("invalid ML-KEM key or ciphertext size")
	}
	dkPKE := dk[:polySize384*mlkemK]
	ek := dk[polySize384*mlkemK : polySize384*mlkemK+mlkemEKSize]
	h := dk[polySize384*mlkemK+mlkemEKSize : polySize384*mlkemK+mlkemEKSize+32]
	z := dk[len(dk)-32:]
	m := mlkemKPKEDecrypt(dkPKE, ct)
	g := sha3_512(append(append([]byte(nil), m...), h...))
	k, r := g[:32], g[32:]
	kBar := shake256(append(append([]byte(nil), z...), ct...), 32)
	ct2 := mlkemKPKEEncrypt(ek, m, r)
	if bytes.Equal(ct2, ct) {
		return append([]byte(nil), k...), nil
	}
	return kBar, nil
}

func mlkemValidEncapsulationKey(ek []byte) bool {
	if len(ek) != mlkemEKSize {
		return false
	}
	for i := 0; i < mlkemK; i++ {
		chunk := ek[i*polySize384 : (i+1)*polySize384]
		decoded := mlkemByteDecode(12, chunk)
		if !bytes.Equal(mlkemByteEncode(12, decoded), chunk) {
			return false
		}
	}
	return true
}
