package main

import (
	"bytes"
	"crypto/rand"
	"errors"
)

const (
	mlkemQ       = 3329
	mlkemN       = 256
	mlkemK       = 3
	mlkemEta1    = 2
	mlkemEta2    = 2
	mlkemDU      = 10
	mlkemDV      = 4
	mlkemEKSize  = 1184
	mlkemDKSize  = 2400
	mlkemCTSize  = 1088
	polySize384  = 384
)

type mlkemPoly [256]int16

func bitRev7(i int) int {
	r := 0
	for j := 0; j < 7; j++ {
		r = (r << 1) | ((i >> uint(j)) & 1)
	}
	return r
}

func modPowQ(base, exp int) int {
	r := 1
	for exp > 0 {
		if exp&1 == 1 {
			r = r * base % mlkemQ
		}
		base = base * base % mlkemQ
		exp >>= 1
	}
	return r
}

func mlkemNTT(f mlkemPoly) mlkemPoly {
	out := f
	i := 1
	for length := 128; length >= 2; length /= 2 {
		for start := 0; start < 256; start += 2 * length {
			zeta := modPowQ(17, bitRev7(i))
			i++
			for j := start; j < start+length; j++ {
				t := zeta * int(out[j+length]) % mlkemQ
				out[j+length] = int16(modQ(int(out[j]) - t))
				out[j] = int16(modQ(int(out[j]) + t))
			}
		}
	}
	return out
}

func modQ(x int) int {
	x %= mlkemQ
	if x < 0 {
		x += mlkemQ
	}
	return x
}

func mlkemINTT(f mlkemPoly) mlkemPoly {
	out := f
	i := 127
	for length := 2; length <= 128; length *= 2 {
		for start := 0; start < 256; start += 2 * length {
			zeta := modPowQ(17, bitRev7(i))
			i--
			for j := start; j < start+length; j++ {
				t := int(out[j])
				out[j] = int16(modQ(t + int(out[j+length])))
				out[j+length] = int16(modQ(zeta * (int(out[j+length]) - t)))
			}
		}
	}
	for j := range out {
		out[j] = int16(int(out[j]) * 3303 % mlkemQ)
	}
	return out
}

func mlkemMultiplyNTT(a, b mlkemPoly) mlkemPoly {
	var out mlkemPoly
	for i := 0; i < 128; i++ {
		a0, a1 := int(a[2*i]), int(a[2*i+1])
		b0, b1 := int(b[2*i]), int(b[2*i+1])
		gamma := modPowQ(17, 2*bitRev7(i)+1)
		out[2*i] = int16(modQ(a0*b0 + a1*b1%mlkemQ*gamma))
		out[2*i+1] = int16(modQ(a0*b1 + a1*b0))
	}
	return out
}

func mlkemAdd(a, b mlkemPoly) mlkemPoly {
	var out mlkemPoly
	for i := range a {
		out[i] = int16(modQ(int(a[i]) + int(b[i])))
	}
	return out
}
func mlkemSub(a, b mlkemPoly) mlkemPoly {
	var out mlkemPoly
	for i := range a {
		out[i] = int16(modQ(int(a[i]) - int(b[i])))
	}
	return out
}

func mlkemSampleNTT(seed []byte) mlkemPoly {
	buf := shake128(seed, 5000)
	var out mlkemPoly
	pos := 0
	idx := 0
	for idx < 256 {
		a0, a1, a2 := int(buf[pos]), int(buf[pos+1]), int(buf[pos+2])
		pos += 3
		d1 := a0 + 256*(a1%16)
		d2 := a1/16 + 16*a2
		if d1 < mlkemQ {
			out[idx] = int16(d1)
			idx++
		}
		if idx < 256 && d2 < mlkemQ {
			out[idx] = int16(d2)
			idx++
		}
	}
	return out
}

func mlkemSampleCBD(data []byte, eta int) mlkemPoly {
	var out mlkemPoly
	for i := 0; i < 256; i++ {
		x, y := 0, 0
		for j := 0; j < eta; j++ {
			bitPos := 2*eta*i + j
			x += int((data[bitPos/8] >> uint(bitPos%8)) & 1)
			bitPos += eta
			y += int((data[bitPos/8] >> uint(bitPos%8)) & 1)
		}
		out[i] = int16(modQ(x - y))
	}
	return out
}

func mlkemPRF(eta int, sigma []byte, b byte) []byte {
	in := append(append([]byte(nil), sigma...), b)
	return shake256(in, 64*eta)
}

func mlkemByteEncode(d int, arr mlkemPoly) []byte {
	out := make([]byte, 0, 32*d)
	var acc uint32
	var accBits uint
	for _, v := range arr {
		acc |= uint32(uint16(v)) << accBits
		accBits += uint(d)
		for accBits >= 8 {
			out = append(out, byte(acc))
			acc >>= 8
			accBits -= 8
		}
	}
	if accBits > 0 {
		out = append(out, byte(acc))
	}
	return out
}

func mlkemByteDecode(d int, data []byte) mlkemPoly {
	var out mlkemPoly
	bitPos := 0
	for i := 0; i < 256; i++ {
		var val int
		for j := 0; j < d; j++ {
			bit := (data[bitPos/8] >> uint(bitPos%8)) & 1
			bitPos++
			val |= int(bit) << uint(j)
		}
		if d == 12 {
			val %= mlkemQ
		}
		out[i] = int16(val)
	}
	return out
}

func mlkemCompress(d int, x mlkemPoly) mlkemPoly {
	var out mlkemPoly
	for i, v := range x {
		out[i] = int16((((int(v) << uint(d)) + mlkemQ/2) / mlkemQ) % (1 << uint(d)))
	}
	return out
}

func mlkemDecompress(d int, y mlkemPoly) mlkemPoly {
	var out mlkemPoly
	for i, v := range y {
		out[i] = int16((mlkemQ*int(v) + (1 << uint(d-1))) >> uint(d))
	}
	return out
}

func mlkemMatrix(rho []byte, transposed bool) [mlkemK][mlkemK]mlkemPoly {
	var a [mlkemK][mlkemK]mlkemPoly
	for i := 0; i < mlkemK; i++ {
		for j := 0; j < mlkemK; j++ {
			var seed []byte
			if !transposed {
				seed = append(append([]byte(nil), rho...), byte(j), byte(i))
			} else {
				seed = append(append([]byte(nil), rho...), byte(i), byte(j))
			}
			a[i][j] = mlkemSampleNTT(seed)
		}
	}
	return a
}

func mlkemKPKEKeyGen(d []byte) (ek, dk []byte) {
	expanded := sha3_512(append(append([]byte(nil), d...), byte(mlkemK)))
	rho, sigma := expanded[:32], expanded[32:]
	a := mlkemMatrix(rho, false)
	nonce := byte(0)
	var s, e [mlkemK]mlkemPoly
	for i := 0; i < mlkemK; i++ {
		s[i] = mlkemSampleCBD(mlkemPRF(mlkemEta1, sigma, nonce), mlkemEta1)
		nonce++
	}
	for i := 0; i < mlkemK; i++ {
		e[i] = mlkemSampleCBD(mlkemPRF(mlkemEta1, sigma, nonce), mlkemEta1)
		nonce++
	}
	var sh, eh, th [mlkemK]mlkemPoly
	for i := 0; i < mlkemK; i++ {
		sh[i] = mlkemNTT(s[i])
		eh[i] = mlkemNTT(e[i])
	}
	for i := 0; i < mlkemK; i++ {
		var acc mlkemPoly
		for j := 0; j < mlkemK; j++ {
			acc = mlkemAdd(acc, mlkemMultiplyNTT(a[i][j], sh[j]))
		}
		th[i] = mlkemAdd(acc, eh[i])
		ek = append(ek, mlkemByteEncode(12, th[i])...)
		dk = append(dk, mlkemByteEncode(12, sh[i])...)
	}
	ek = append(ek, rho...)
	return ek, dk
}

func mlkemKPKEEncrypt(ek, m, r []byte) []byte {
	var th [mlkemK]mlkemPoly
	for i := 0; i < mlkemK; i++ {
		th[i] = mlkemByteDecode(12, ek[i*polySize384:(i+1)*polySize384])
	}
	rho := ek[polySize384*mlkemK:]
	at := mlkemMatrix(rho, true)
	nonce := byte(0)
	var y, e1 [mlkemK]mlkemPoly
	for i := 0; i < mlkemK; i++ {
		y[i] = mlkemSampleCBD(mlkemPRF(mlkemEta1, r, nonce), mlkemEta1)
		nonce++
	}
	for i := 0; i < mlkemK; i++ {
		e1[i] = mlkemSampleCBD(mlkemPRF(mlkemEta2, r, nonce), mlkemEta2)
		nonce++
	}
	e2 := mlkemSampleCBD(mlkemPRF(mlkemEta2, r, nonce), mlkemEta2)
	var yh [mlkemK]mlkemPoly
	for i := 0; i < mlkemK; i++ {
		yh[i] = mlkemNTT(y[i])
	}
	var ct []byte
	for i := 0; i < mlkemK; i++ {
		var acc mlkemPoly
		for j := 0; j < mlkemK; j++ {
			acc = mlkemAdd(acc, mlkemMultiplyNTT(at[i][j], yh[j]))
		}
		u := mlkemAdd(mlkemINTT(acc), e1[i])
		ct = append(ct, mlkemByteEncode(mlkemDU, mlkemCompress(mlkemDU, u))...)
	}
	mu := mlkemDecompress(1, mlkemByteDecode(1, m))
	var acc mlkemPoly
	for j := 0; j < mlkemK; j++ {
		acc = mlkemAdd(acc, mlkemMultiplyNTT(th[j], yh[j]))
	}
	v := mlkemAdd(mlkemAdd(mlkemINTT(acc), e2), mu)
	ct = append(ct, mlkemByteEncode(mlkemDV, mlkemCompress(mlkemDV, v))...)
	return ct
}

func mlkemKPKEDecrypt(dk, ct []byte) []byte {
	c1 := ct[:32*mlkemDU*mlkemK]
	c2 := ct[32*mlkemDU*mlkemK:]
	v := mlkemDecompress(mlkemDV, mlkemByteDecode(mlkemDV, c2))
	var acc mlkemPoly
	for i := 0; i < mlkemK; i++ {
		u := mlkemDecompress(mlkemDU, mlkemByteDecode(mlkemDU, c1[i*32*mlkemDU:(i+1)*32*mlkemDU]))
		sh := mlkemByteDecode(12, dk[i*polySize384:(i+1)*polySize384])
		acc = mlkemAdd(acc, mlkemMultiplyNTT(sh, mlkemNTT(u)))
	}
	w := mlkemSub(v, mlkemINTT(acc))
	return mlkemByteEncode(1, mlkemCompress(1, w))
}

func mlkemKeyGenFromSeed(seed []byte) (ek, dk []byte) {
	// seed is d || z, 32 bytes each.
	ek, dkPKE := mlkemKPKEKeyGen(seed[:32])
	dk = append([]byte(nil), dkPKE...)
	dk = append(dk, ek...)
	dk = append(dk, sha3_256(ek)...)
	dk = append(dk, seed[32:64]...)
	return ek, dk
}

func mlkemEncapsulate(ek []byte) (shared, ct []byte, err error) {
	m := make([]byte, 32)
	if _, err := rand.Read(m); err != nil {
		return nil, nil, err
	}
	g := sha3_512(append(append([]byte(nil), m...), sha3_256(ek)...))
	ct = mlkemKPKEEncrypt(ek, m, g[32:])
	return g[:32], ct, nil
}

func mlkemDecapsulate(dk, ct []byte) ([]byte, error) {
	if len(dk) != mlkemDKSize || len(ct) != mlkemCTSize {
		return nil, errors.New("invalid ML-KEM key or ciphertext size")
	}
	dkPKE := dk[:polySize384*mlkemK]
	ek := dk[polySize384*mlkemK : polySize384*mlkemK+mlkemEKSize]
	h := dk[polySize384*mlkemK+mlkemEKSize : polySize384*mlkemK+mlkemEKSize+32]
	z := dk[len(dk)-32:]
	m := mlkemKPKEDecrypt(dkPKE, ct)
	g := sha3_512(append(append([]byte(nil), m...), h...))
	k, r := g[:32], g[32:]
	kBar := shake256(append(append([]byte(nil), z...), ct...), 32)
	ct2 := mlkemKPKEEncrypt(ek, m, r)
	if bytes.Equal(ct2, ct) {
		return append([]byte(nil), k...), nil
	}
	return kBar, nil
}

func mlkemValidEncapsulationKey(ek []byte) bool {
	if len(ek) != mlkemEKSize {
		return false
	}
	for i := 0; i < mlkemK; i++ {
		chunk := ek[i*polySize384 : (i+1)*polySize384]
		decoded := mlkemByteDecode(12, chunk)
		if !bytes.Equal(mlkemByteEncode(12, decoded), chunk) {
			return false
		}
	}
	return true
}
