func pbkdf2SHA256(password, salt []byte, iter, keyLen int) []byte {
	var dk []byte
	for block := 1; len(dk) < keyLen; block++ {
		m := hmac.New(sha256.New, password)
		m.Write(salt)
		var blk [4]byte
		binary.BigEndian.PutUint32(blk[:], uint32(block))
		m.Write(blk[:])
		u := m.Sum(nil)
		t := append([]byte(nil), u...)
		for i := 1; i < iter; i++ {
			m = hmac.New(sha256.New, password)
			m.Write(u)
			u = m.Sum(nil)
			for j := range t {
				t[j] ^= u[j]
			}
		}
		dk = append(dk, t...)
	}
	return dk[:keyLen]
}

func salsa208(b *[64]byte) {
	var x [16]uint32
	for i := 0; i < 16; i++ {
		x[i] = binary.LittleEndian.Uint32(b[i*4 : (i+1)*4])
	}
	orig := x
	quarter := func(y0, y1, y2, y3 int) {
		x[y1] ^= bits.RotateLeft32(x[y0]+x[y3], 7)
		x[y2] ^= bits.RotateLeft32(x[y1]+x[y0], 9)
		x[y3] ^= bits.RotateLeft32(x[y2]+x[y1], 13)
		x[y0] ^= bits.RotateLeft32(x[y3]+x[y2], 18)
	}
	for i := 0; i < 4; i++ {
		// column rounds
		quarter(0, 4, 8, 12)
		quarter(5, 9, 13, 1)
		quarter(10, 14, 2, 6)
		quarter(15, 3, 7, 11)
		// row rounds
		quarter(0, 1, 2, 3)
		quarter(5, 6, 7, 4)
		quarter(10, 11, 8, 9)
		quarter(15, 12, 13, 14)
	}
	for i := 0; i < 16; i++ {
		binary.LittleEndian.PutUint32(b[i*4:(i+1)*4], x[i]+orig[i])
	}
}

func blockMix(b, y []byte, r int) {
	var x [64]byte
	copy(x[:], b[(2*r-1)*64:(2*r)*64])
	for i := 0; i < 2*r; i++ {
		for j := 0; j < 64; j++ {
			x[j] ^= b[i*64+j]
		}
		salsa208(&x)
		copy(y[i*64:(i+1)*64], x[:])
	}
	for i := 0; i < r; i++ {
		copy(b[i*64:(i+1)*64], y[(2*i)*64:(2*i+1)*64])
	}
	for i := 0; i < r; i++ {
		copy(b[(r+i)*64:(r+i+1)*64], y[(2*i+1)*64:(2*i+2)*64])
	}
}

func integerify(b []byte, r int) uint64 {
	last := b[(2*r-1)*64:]
	return binary.LittleEndian.Uint64(last[:8])
}

func romix(b []byte, n, r int) {
	blockSize := 128 * r
	v := make([]byte, n*blockSize)
	y := make([]byte, blockSize)
	x := append([]byte(nil), b...)
	for i := 0; i < n; i++ {
		copy(v[i*blockSize:(i+1)*blockSize], x)
		blockMix(x, y, r)
	}
	for i := 0; i < n; i++ {
		j := int(integerify(x, r) & uint64(n-1))
		vj := v[j*blockSize : (j+1)*blockSize]
		for k := range x {
			x[k] ^= vj[k]
		}
		blockMix(x, y, r)
	}
	copy(b, x)
}

func scryptKey(password, salt []byte, n, r, p, keyLen int) ([]byte, error) {
	if n <= 1 || n&(n-1) != 0 {
		return nil, errors.New("scrypt: N is not a power of two")
	}
	if r <= 0 || p <= 0 {
		return nil, errors.New("scrypt: invalid parameters")
	}
	// Keep allocations bounded by the caller's own parameter checks.
	b := pbkdf2SHA256(password, salt, 1, p*128*r)
	for i := 0; i < p; i++ {
		romix(b[i*128*r:(i+1)*128*r], n, r)
	}
	return pbkdf2SHA256(password, b, 1, keyLen), nil
}
