}

// stanzaReader reads a sequence of individual stanzas (used for the plugin
// protocol as well as age headers).
type stanzaReader struct {
	lr *lineReader
}

func parseStanzaOpening(line string) (*Stanza, error) {
	if !strings.HasPrefix(line, "-> ") {
		return nil, fmt.Errorf("failed to parse header: malformed stanza: %q", line)
	}
	content := strings.TrimSuffix(line, "\n")
	parts := strings.Split(content[3:], " ")
	for _, p := range parts {
		if p == "" {
			return nil, fmt.Errorf("failed to parse header: malformed stanza: %q", line)
		}
		for i := 0; i < len(p); i++ {
			if p[i] < 33 || p[i] > 126 {
				return nil, fmt.Errorf("failed to parse header: malformed stanza: %q", line)
			}
		}
	}
	return &Stanza{Type: parts[0], Args: append([]string(nil), parts[1:]...)}, nil
}

func (sr *stanzaReader) readStanza() (*Stanza, error) {
	line, err := sr.lr.readLine()
	if err != nil {
		return nil, err
	}
	if !strings.HasPrefix(line, "->") {
		return nil, fmt.Errorf("failed to parse header: malformed stanza opening line: %q", line)
	}
	st, err := parseStanzaOpening(line)
	if err != nil {
		return nil, err
	}
	for {
		bodyLine, err := sr.lr.readLine()
		if err != nil {
			return nil, fmt.Errorf("failed to parse header: failed to read line: %w", err)
		}
		body, short, err := parseStanzaBodyLine(bodyLine)
		if err != nil {
			return nil, err
		}
		st.Body = append(st.Body, body...)
		if short {
			break
		}
	}
	return st, nil
