	if !strings.HasPrefix(line, "->") {
		return nil, fmt.Errorf("failed to parse header: malformed stanza opening line: %q", line)
	}
	st, err := parseStanzaOpening(line)
	if err != nil {
		return nil, err
	}
	for {
		bodyLine, err := sr.lr.readLine()
		if err != nil {
			return nil, fmt.Errorf("failed to parse header: failed to read line: %w", err)
		}
		body, short, err := parseStanzaBodyLine(bodyLine)
		if err != nil {
			return nil, err
		}
		st.Body = append(st.Body, body...)
		if short {
			break
		}
	}
	return st, nil
}

func parseStanzaBodyLine(line string) ([]byte, bool, error) {
	if strings.HasPrefix(line, "--- ") {
		return nil, false, fmt.Errorf("failed to parse header: malformed body line %q: stanza ended without a short line\nnote: this might be a file encrypted with an old beta version of age or rage; use age v1.0.0-beta6 or rage to decrypt it", line)
	}
	content := strings.TrimSuffix(line, "\n")
	decoded, err := base64.RawStdEncoding.Strict().DecodeString(content)
	if err != nil {
		return nil, false, fmt.Errorf("failed to parse header: parsing age header: malformed body line %q: %w", line, err)
	}
	if len(content) > 64 {
		return nil, false, fmt.Errorf("failed to parse header: parsing age header: malformed body line %q: too long", line)
	}
	return decoded, len(decoded) < 48, nil
}

type headerResult struct {
	Stanzas   []*Stanza
	MAC       []byte
	MACBytes  []byte // bytes covered by the MAC, ending in "---"
	Remaining *bufio.Reader
}

func parseHeader(in io.Reader) (*headerResult, error) {
	br := bufio.NewReader(in)
	br, armored := detectArmor(br)
	var reader *bufio.Reader
	var ar *armorReader
	if armored {
		ar = newArmorReader(br)
		reader = bufio.NewReader(ar)
	} else {
		reader = br
	}
	// PowerShell CRLF corruption detection: an intro immediately followed
	// by a carriage return.
	if peek, err := reader.Peek(len(ageIntro) + 1); err == nil {
		if string(peek[:len(ageIntro)]) == ageIntro && peek[len(ageIntro)] == '\r' {
			return nil, errCRLFIntro
		}
	}
	lr := &lineReader{r: reader}
	introLine, err := lr.readLine()
	if err != nil {
		if err == io.EOF {
			return nil, errors.New("parsing age header: file is empty")
		}
		return nil, fmt.Errorf("parsing age header: failed to read intro: %w", err)
	}
	if introLine != ageIntro+"\n" {
		return nil, fmt.Errorf("parsing age header: unexpected intro: %q", introLine)
	}
	macBytes := append([]byte(nil), introLine...)
	var stanzas []*Stanza
	var footerLine string
	for {
		line, err := lr.readLine()
		if err != nil {
			if err == io.EOF {
				if line == "" {
					return nil, errors.New("parsing age header: failed to read header: EOF")
				}
				return nil, errors.New("failed to read header: EOF")
			}
			return nil, fmt.Errorf("failed to parse header: failed to read line: %w", err)
		}
		if strings.HasPrefix(line, "---") {
			footerLine = line
			macBytes = append(macBytes, []byte("---")...)
			break
		}
		macBytes = append(macBytes, line...)
		if !strings.HasPrefix(line, "->") {
			return nil, fmt.Errorf("failed to parse header: malformed stanza opening line: %q", line)
		}
		st, err := parseStanzaOpening(line)
		if err != nil {
			return nil, err
		}
		for {
			bodyLine, err := lr.readLine()
			if err != nil {
				return nil, fmt.Errorf("failed to parse header: failed to read line: %w", err)
			}
			macBytes = append(macBytes, bodyLine...)
			body, short, err := parseStanzaBodyLine(bodyLine)
			if err != nil {
				return nil, err
			}
			st.Body = append(st.Body, body...)
			if short {
				break
			}
		}
		stanzas = append(stanzas, st)
	}
	if !strings.HasPrefix(footerLine, "--- ") {
		return nil, fmt.Errorf("parsing age header: malformed closing line: %q", footerLine)
	}
	macString := strings.TrimSuffix(footerLine[4:], "\n")
	mac, err := base64.RawStdEncoding.Strict().DecodeString(macString)
	if err != nil {
		return nil, fmt.Errorf("parsing age header: malformed closing line %q: %w", footerLine, err)
	}
	if len(mac) != 32 {
		return nil, fmt.Errorf("parsing age header: malformed closing line %q: <nil>", footerLine)
	}
	_ = ar
	return &headerResult{Stanzas: stanzas, MAC: mac, MACBytes: macBytes, Remaining: reader}, nil
}

func detectArmor(br *bufio.Reader) (*bufio.Reader, bool) {
	var prefix []byte
	armored := false
	for {
		line, err := br.ReadString('\n')
		prefix = append(prefix, line...)
		if strings.TrimSpace(line) == "" {
			if err != nil {
				break
			}
			continue
		}
		left := strings.TrimLeft(line, " \t\r\n\v\f")
		if strings.HasPrefix(left, armorBegin) {
			armored = true
		}
		break
	}
	combined := io.MultiReader(bytes.NewReader(prefix), br)
	return bufio.NewReader(combined), armored
}

type armorReader struct {
	r              *bufio.Reader
	buf            []byte
	started        bool
	ended          bool
	sawShort       bool
	trailingChecked bool
	err            error
}

func newArmorReader(br *bufio.Reader) *armorReader { return &armorReader{r: br} }

func armorErrorf(format string, args ...interface{}) error {
	return fmt.Errorf("invalid armor: "+format, args...)
}

func trimLineEnding(line string) string {
	line = strings.TrimSuffix(line, "\n")
	line = strings.TrimSuffix(line, "\r")
	return line
}

func (ar *armorReader) readRawLine() (string, error) {
	return ar.r.ReadString('\n')
}

func (ar *armorReader) fill() error {
	if ar.err != nil {
		return ar.err
	}
	if ar.ended {
		return io.EOF
	}
	if !ar.started {
		for {
			line, err := ar.readRawLine()
			if err != nil && line == "" {
				if err == io.EOF {
					ar.err = armorErrorf("unexpected EOF")
				} else {
					ar.err = err
				}
				return ar.err
			}
			if strings.TrimSpace(line) == "" {
				if err != nil {
					ar.err = armorErrorf("unexpected EOF")
					return ar.err
				}
				continue
			}
			stripped := trimLineEnding(line)
			if stripped != armorBegin {
				ar.err = armorErrorf("invalid first line: %q", stripped)
				return ar.err
			}
			ar.started = true
			if err == io.EOF {
				// Marker was the entire input; the next fill will hit
				// unexpected EOF, represented by leaving started set
				// and letting the data-line reader see EOF. To avoid
				// consuming it here, proceed to read a data line
				// which will report EOF.
			}
			break
		}
	}
	line, err := ar.readRawLine()
	if err != nil && line == "" {
		if err == io.EOF {
			ar.err = armorErrorf("unexpected EOF")
		} else {
			ar.err = err
		}
		return ar.err
	}
	stripped := trimLineEnding(line)
	if ar.sawShort {
		if stripped != armorEnd {
			ar.err = armorErrorf("invalid closing line: %q", stripped)
			return ar.err
		}
		ar.ended = true
		return io.EOF
	}
	if stripped == armorEnd || strings.HasPrefix(stripped, "-----END") {
		if stripped != armorEnd {
			ar.err = armorErrorf("invalid closing line: %q", stripped)
			return ar.err
		}
		ar.ended = true
		return io.EOF
	}
	if strings.TrimSpace(stripped) == "" {
		ar.err = armorErrorf("empty line in armored data")
		return ar.err
	}
	if len(stripped) > 64 {
		ar.err = armorErrorf("column limit exceeded")
		return ar.err
	}
	decoded, derr := base64.StdEncoding.Strict().DecodeString(stripped)
	if derr != nil {
		ar.err = fmt.Errorf("invalid armor: %w", derr)
		return ar.err
	}
	if len(decoded) < 48 {
		ar.sawShort = true
	}
	ar.buf = decoded
	// If this data line was terminated by EOF rather than a newline, the
	// following fill will encounter EOF and correctly report it.
	_ = err
	return nil
}

func (ar *armorReader) checkTrailing() error {
	if ar.trailingChecked {
		return io.EOF
	}
	ar.trailingChecked = true
	rest, err := io.ReadAll(ar.r)
	if err != nil {
		return err
	}
	if len(bytes.TrimSpace(rest)) != 0 {
		return armorErrorf("trailing data after armored file")
	}
	return io.EOF
}

func (ar *armorReader) Read(p []byte) (int, error) {
	for len(ar.buf) == 0 {
		if ar.ended {
			return 0, ar.checkTrailing()
		}
		if err := ar.fill(); err != nil {
			if err == io.EOF && ar.ended {
				return 0, ar.checkTrailing()
			}
			return 0, err
		}
	}
	n := copy(p, ar.buf)
	ar.buf = ar.buf[n:]
	return n, nil
}

type armorWriter struct {
	w           io.Writer
	buf         []byte
	wroteHeader bool
	closed      bool
}

func newArmorWriter(w io.Writer) *armorWriter { return &armorWriter{w: w} }

func (aw *armorWriter) Write(p []byte) (int, error) {
	if !aw.wroteHeader {
		if _, err := io.WriteString(aw.w, armorBegin+"\n"); err != nil {
			return 0, err
		}
		aw.wroteHeader = true
	}
	aw.buf = append(aw.buf, p...)
	for len(aw.buf) >= 48 {
		line := base64.StdEncoding.EncodeToString(aw.buf[:48])
		if _, err := io.WriteString(aw.w, line+"\n"); err != nil {
			return 0, err
		}
		aw.buf = aw.buf[48:]
	}
	return len(p), nil
}

func (aw *armorWriter) Close() error {
	if aw.closed {
		return nil
	}
	aw.closed = true
	if !aw.wroteHeader {
		if _, err := io.WriteString(aw.w, armorBegin+"\n"); err != nil {
			return err
		}
		aw.wroteHeader = true
	}
	if len(aw.buf) > 0 {
		line := base64.StdEncoding.EncodeToString(aw.buf)
		if _, err := io.WriteString(aw.w, line+"\n"); err != nil {
			return err
		}
		aw.buf = nil
	}
	_, err := io.WriteString(aw.w, armorEnd+"\n")
	return err
}

const streamChunkSize = 64 * 1024
const streamTagSize = 16

type streamWriter struct {
	w       io.Writer
	key     []byte
	counter uint64
	buf     []byte
	closed  bool
}

func streamNonce(counter uint64, last bool) []byte {
	nonce := make([]byte, 12)
	// 11-byte big-endian counter followed by the last-chunk flag.
	for i := 10; i >= 0; i-- {
		nonce[i] = byte(counter)
		counter >>= 8
	}
	if last {
		nonce[11] = 1
	}
	return nonce
}

func (sw *streamWriter) seal(chunk []byte, last bool) error {
	nonce := streamNonce(sw.counter, last)
	sw.counter++
	ct := chachaPoly1305Seal(sw.key, nonce, chunk, nil)
	_, err := sw.w.Write(ct)
	return err
}

func (sw *streamWriter) Write(p []byte) (int, error) {
	sw.buf = append(sw.buf, p...)
	for len(sw.buf) > streamChunkSize {
		if err := sw.seal(sw.buf[:streamChunkSize], false); err != nil {
			return 0, err
		}
		sw.buf = append([]byte(nil), sw.buf[streamChunkSize:]...)
	}
	return len(p), nil
}

func (sw *streamWriter) Close() error {
	if sw.closed {
		return nil
	}
	sw.closed = true
	return sw.seal(sw.buf, true)
}

type streamReader struct {
	r       *bufio.Reader
	key     []byte
	counter uint64
	buf     []byte
	off     int
	done    bool
	err     error
}

func (sr *streamReader) fill() error {
	if sr.done {
		return io.EOF
	}
	chunk := make([]byte, streamChunkSize+streamTagSize)
	n, readErr := io.ReadFull(sr.r, chunk)
	if n == len(chunk) {
		_, peekErr := sr.r.Peek(1)
		if peekErr != nil && peekErr != io.EOF {
			return peekErr
		}
		last := peekErr == io.EOF
		pt, err := chachaPoly1305Open(sr.key, streamNonce(sr.counter, last), chunk, nil)
		if err != nil {
			return errStreamAuth
		}
		sr.counter++
		sr.buf = pt
		sr.off = 0
		if last {
			sr.done = true
		}
		return nil
	}
	if readErr != nil && readErr != io.EOF && readErr != io.ErrUnexpectedEOF {
		return readErr
	}
	if n == 0 {
		return io.ErrUnexpectedEOF
	}
	pt, err := chachaPoly1305Open(sr.key, streamNonce(sr.counter, true), chunk[:n], nil)
	if err != nil {
		return errStreamAuth
	}
	sr.counter++
	sr.buf = pt
	sr.off = 0
	sr.done = true
	return nil
}

func (sr *streamReader) Read(p []byte) (int, error) {
	for sr.off >= len(sr.buf) {
		if sr.err != nil {
			return 0, sr.err
		}
		if err := sr.fill(); err != nil {
			sr.err = err
			return 0, err
		}
	}
	n := copy(p, sr.buf[sr.off:])
	sr.off += n
	return n, nil
}

type Recipient interface {
	Wrap(fileKey []byte) ([]*Stanza, []string, error)
}

type Identity interface {
	Unwrap(stanzas []*Stanza) ([]byte, error)
}

func headerMAC(fileKey []byte, macBytes []byte) []byte {
	macKey := hkdfSHA256(fileKey, nil, []byte("header"), 32)
	h := hmac.New(sha256.New, macKey)
	h.Write(macBytes)
	return h.Sum(nil)
}

type labelsMismatchError struct {
	first, second []string
}

func (e *labelsMismatchError) Error() string {
	return fmt.Sprintf("incompatible recipients: %q and %q can't be mixed", e.first, e.second)
}

func labelsEqual(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func ageEncrypt(out io.Writer, recipients []Recipient) (io.WriteCloser, error) {
	fileKey := make([]byte, 16)
	if _, err := rand.Read(fileKey); err != nil {
		return nil, err
	}
	var stanzas []*Stanza
	var labels []string
	for i, r := range recipients {
		ss, l, err := r.Wrap(fileKey)
		if err != nil {
			return nil, fmt.Errorf("failed to wrap key for recipient #%d: %w", i, err)
		}
		if i == 0 {
			labels = append([]string(nil), l...)
		} else if !labelsEqual(labels, l) {
			return nil, &labelsMismatchError{first: labels, second: append([]string(nil), l...)}
		}
		stanzas = append(stanzas, ss...)
	}
	var header bytes.Buffer
	header.WriteString(ageIntro + "\n")
	for _, s := range stanzas {
		header.Write(s.marshal())
	}
	headerBytesForMAC := append(append([]byte(nil), header.Bytes()...), []byte("---")...)
	mac := headerMAC(fileKey, headerBytesForMAC)
	header.WriteString("--- ")
	header.WriteString(base64.RawStdEncoding.EncodeToString(mac))
	header.WriteByte('\n')
	if _, err := out.Write(header.Bytes()); err != nil {
		return nil, fmt.Errorf("failed to write header: %w", err)
	}
	nonce := make([]byte, 16)
	if _, err := rand.Read(nonce); err != nil {
		return nil, err
	}
	if _, err := out.Write(nonce); err != nil {
		return nil, err
	}
	streamKey := hkdfSHA256(fileKey, nonce, []byte("payload"), 32)
	return &streamWriter{w: out, key: streamKey}, nil
}

type decryptionResult struct {
	Reader  io.Reader
	Stanzas []*Stanza
}

func ageDecrypt(in io.Reader, identities []Identity) (*decryptionResult, error) {
	hdr, err := parseHeader(in)
	if err != nil {
		if errors.Is(err, errCRLFIntro) {
			return nil, err
		}
		return nil, fmt.Errorf("failed to read header: %w", err)
	}
	var fileKey []byte
	for _, id := range identities {
		fk, err := id.Unwrap(hdr.Stanzas)
		if err != nil {
			if errors.Is(err, errNoIdentityMatch) {
				continue
			}
			return nil, err
		}
		if fk != nil {
			fileKey = fk
			break
		}
	}
	if fileKey == nil {
		return &decryptionResult{Stanzas: hdr.Stanzas}, errNoIdentityMatch
	}
	expectedMAC := headerMAC(fileKey, hdr.MACBytes)
	if !hmac.Equal(expectedMAC, hdr.MAC) {
		return nil, errBadHeaderMAC
	}
	nonce := make([]byte, 16)
	if _, err := io.ReadFull(hdr.Remaining, nonce); err != nil {
		return nil, fmt.Errorf("failed to read nonce: %w", err)
	}
	streamKey := hkdfSHA256(fileKey, nonce, []byte("payload"), 32)
	return &decryptionResult{Reader: &streamReader{r: hdr.Remaining, key: streamKey}, Stanzas: hdr.Stanzas}, nil
}
