func b64RawEncode(b []byte) string { return base64.RawStdEncoding.EncodeToString(b) }
func b64RawDecode(s string) ([]byte, error) {
	return base64.RawStdEncoding.Strict().DecodeString(s)
}

func wrapFileKey(wrappingKey, fileKey []byte) []byte {
	return chachaPoly1305Seal(wrappingKey, make([]byte, 12), fileKey, nil)
}

// X25519

type X25519Recipient struct {
	pub    []byte
	pubKey *ecdh.PublicKey
}

func newX25519RecipientFromPublic(pub []byte) (*X25519Recipient, error) {
	k, err := ecdh.X25519().NewPublicKey(pub)
	if err != nil {
		return nil, errors.New("invalid X25519 public key")
	}
	return &X25519Recipient{pub: append([]byte(nil), pub...), pubKey: k}, nil
}

func parseX25519Recipient(s string) (*X25519Recipient, error) {
	hrp, data, err := bech32Decode(s)
	if err != nil {
		return nil, err
	}
	if hrp != "age" || len(data) != 32 {
		return nil, errors.New("invalid X25519 public key")
	}
	return newX25519RecipientFromPublic(data)
}

func (r *X25519Recipient) String() string {
	s, _ := bech32Encode("age", r.pub)
	return s
}

func (r *X25519Recipient) Wrap(fileKey []byte) ([]*Stanza, []string, error) {
	eph, err := ecdh.X25519().GenerateKey(rand.Reader)
	if err != nil {
		return nil, nil, err
	}
	shared, err := eph.ECDH(r.pubKey)
	if err != nil {
		return nil, nil, err
	}
	ephPub := eph.PublicKey().Bytes()
	salt := append(append([]byte(nil), ephPub...), r.pub...)
	wrappingKey := hkdfSHA256(shared, salt, []byte("age-encryption.org/v1/X25519"), 32)
	return []*Stanza{{Type: "X25519", Args: []string{b64RawEncode(ephPub)}, Body: wrapFileKey(wrappingKey, fileKey)}}, nil, nil
}

