	secret []byte
	priv   *ecdh.PrivateKey
	pub    []byte
}

func newX25519Identity(secret []byte) (*X25519Identity, error) {
	k, err := ecdh.X25519().NewPrivateKey(secret)
	if err != nil {
		return nil, errors.New("invalid X25519 secret key")
	}
	return &X25519Identity{secret: append([]byte(nil), secret...), priv: k, pub: k.PublicKey().Bytes()}, nil
}

func parseX25519Identity(s string) (*X25519Identity, error) {
	hrp, data, err := bech32Decode(s)
	if err != nil {
