	pub *sshPublicKey
}

func (r *SSHRSARecipient) Wrap(fileKey []byte) ([]*Stanza, []string, error) {
	ct, err := rsa.EncryptOAEP(sha256.New(), rand.Reader, r.pub.rsa, fileKey, []byte("age-encryption.org/v1/ssh-rsa"))
	if err != nil {
