		}
		return fileKey, nil
	}
	return nil, errNoIdentityMatch
}

func bytesEqual(a, b []byte) bool {
	if len(a) != len(b) {
		return false
	}
	var v byte
	for i := range a {
		v |= a[i] ^ b[i]
	}
	return v == 0
}

// SSH Ed25519

func sshEd25519Tweak(marshal []byte) *big.Int {
	t := hkdfSHA256(nil, marshal, []byte("age-encryption.org/v1/ssh-ed25519"), 32)
