	pub *sshPublicKey
}

func (r *SSHEd25519Recipient) Wrap(fileKey []byte) ([]*Stanza, []string, error) {
	recipientPoint, err := edDecodePoint(r.pub.ed)
	if err != nil {
		return nil, nil, err
	}
	tweak := sshEd25519Tweak(r.pub.marshal)
	random := make([]byte, 32)
	if _, err := rand.Read(random); err != nil {
		return nil, nil, err
	}
	ephScalar := edScalarFromClampedBytes(random)
	tweaked := new(big.Int).Mod(new(big.Int).Mul(ephScalar, tweak), edL)
	base := &edPoint{edBaseX, edBaseY}
	ephPoint := edScalarMult(base, tweaked)
	ephShare := edPointToMontgomery(ephPoint)
	sharedPoint := edScalarMult(recipientPoint, tweaked)
	shared := edPointToMontgomery(sharedPoint)
	theirMont := edPointToMontgomery(recipientPoint)
	salt := append(append([]byte(nil), ephShare...), theirMont...)
	wrappingKey := hkdfSHA256(shared, salt, []byte("age-encryption.org/v1/ssh-ed25519"), 32)
	st := &Stanza{Type: "ssh-ed25519", Args: []string{b64RawEncode(r.pub.tag()), b64RawEncode(ephShare)}, Body: wrapFileKey(wrappingKey, fileKey)}
	return []*Stanza{st}, nil, nil
}

type SSHEd25519Identity struct {
	seed []byte // 32-byte Ed25519 seed
	pub  *sshPublicKey
}

func (id *SSHEd25519Identity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	for _, s := range stanzas {
		if s.Type != "ssh-ed25519" {
			continue
		}
		if len(s.Args) != 2 {
			return nil, errors.New("invalid ssh-ed25519 recipient block")
