		}
		ephShare, err := b64RawDecode(s.Args[1])
		if err != nil {
			return nil, fmt.Errorf("failed to parse ssh-ed25519 recipient: %w", err)
		}
		if len(tag) != 4 || len(ephShare) != 32 {
			return nil, errors.New("invalid ssh-ed25519 recipient block")
		}
		if !bytesEqual(tag, id.pub.tag()) {
			continue
		}
		if len(s.Body) != 32 {
			return nil, errors.New("invalid ssh-ed25519 recipient block")
		}
		ephPoint, err := edPointFromMontgomery(ephShare)
		if err != nil {
			continue
		}
		tweak := sshEd25519Tweak(id.pub.marshal)
		privScalar := edPrivateScalar(id.seed)
		tweaked := new(big.Int).Mod(new(big.Int).Mul(privScalar, tweak), edL)
		sharedPoint := edScalarMult(ephPoint, tweaked)
		shared := edPointToMontgomery(sharedPoint)
		recipientPoint, err := edDecodePoint(id.pub.ed)
		if err != nil {
			return nil, err
		}
		theirMont := edPointToMontgomery(recipientPoint)
		salt := append(append([]byte(nil), ephShare...), theirMont...)
		wrappingKey := hkdfSHA256(shared, salt, []byte("age-encryption.org/v1/ssh-ed25519"), 32)
		fileKey, err := chachaPoly1305Open(wrappingKey, make([]byte, 12), s.Body, nil)
		if err != nil {
			continue
		}
		return fileKey, nil
	}
	return nil, errNoIdentityMatch
}
