cat > ssh.go << 'EOF'
package main

import (
	"bytes"
	"crypto/dsa"
	"crypto/ecdsa"
	"crypto/ed25519"
	"crypto/elliptic"
	"crypto/rsa"
	"crypto/sha256"
	"crypto/x509"
	"encoding/base64"
	"encoding/binary"
	"encoding/pem"
	"errors"
	"fmt"
	"math/big"
	"os"
	"strings"
)

type sshPublicKey struct {
	typ     string
	marshal []byte
	rsa     *rsa.PublicKey
	ed      []byte
}

func (k *sshPublicKey) tag() []byte {
	h := sha256.Sum256(k.marshal)
	return append([]byte(nil), h[:4]...)
}

type wireReader struct {
	b   []byte
	off int
}

func (r *wireReader) readUint32() (uint32, error) {
	if len(r.b)-r.off < 4 {
		return 0, errors.New("short buffer")
	}
	v := binary.BigEndian.Uint32(r.b[r.off : r.off+4])
	r.off += 4
	return v, nil
}
func (r *wireReader) readString() ([]byte, error) {
	n, err := r.readUint32()
	if err != nil {
		return nil, err
	}
	if uint64(len(r.b)-r.off) < uint64(n) {
		return nil, errors.New("short buffer")
	}
	v := append([]byte(nil), r.b[r.off:r.off+int(n)]...)
	r.off += int(n)
	return v, nil
}
func (r *wireReader) readMPInt() (*big.Int, error) {
	b, err := r.readString()
	if err != nil {
		return nil, err
	}
	return mpintToBig(b), nil
}
func mpintToBig(b []byte) *big.Int {
	if len(b) == 0 {
		return big.NewInt(0)
	}
	v := new(big.Int).SetBytes(b)
	if b[0]&0x80 != 0 {
		// Two's complement negative value.
		max := new(big.Int).Lsh(big.NewInt(1), uint(len(b)*8))
		v.Sub(v, max)
	}
	return v
}
func writeSSHString(buf *bytes.Buffer, b []byte) {
	var l [4]byte
	binary.BigEndian.PutUint32(l[:], uint32(len(b)))
	buf.Write(l[:])
	buf.Write(b)
}
func writeSSHMPInt(buf *bytes.Buffer, v *big.Int) {
	var b []byte
	if v.Sign() != 0 {
		b = v.Bytes()
		if b[0]&0x80 != 0 {
			b = append([]byte{0}, b...)
		}
	}
	writeSSHString(buf, b)
}

func marshalSSHPublicKey(k *sshPublicKey) []byte {
	var buf bytes.Buffer
	writeSSHString(&buf, []byte(k.typ))
	switch k.typ {
	case "ssh-rsa":
		writeSSHMPInt(&buf, big.NewInt(int64(k.rsa.E)))
		writeSSHMPInt(&buf, k.rsa.N)
	case "ssh-ed25519":
		writeSSHString(&buf, k.ed)
	default:
		return k.marshal
	}
	return buf.Bytes()
}

func newSSHRSAPublicKey(pub *rsa.PublicKey) *sshPublicKey {
	k := &sshPublicKey{typ: "ssh-rsa", rsa: pub}
	k.marshal = marshalSSHPublicKey(k)
	return k
}
func newSSHEd25519PublicKey(pub []byte) *sshPublicKey {
	k := &sshPublicKey{typ: "ssh-ed25519", ed: append([]byte(nil), pub...)}
	k.marshal = marshalSSHPublicKey(k)
	return k
}

// parseSSHPublicKeyBlob parses the SSH wire encoding. For key types that
// are valid SSH keys but unsupported by age it returns a key containing
// only its type.
func parseSSHPublicKeyBlob(blob []byte) (*sshPublicKey, error) {
	r := &wireReader{b: blob}
	typeBytes, err := r.readString()
	if err != nil {
		return nil, errors.New("ssh: no key found")
	}
	typ := string(typeBytes)
	switch typ {
	case "ssh-ed25519":
		pub, err := r.readString()
		if err != nil || len(pub) != 32 {
			return nil, errors.New("ssh: no key found")
		}
		k := newSSHEd25519PublicKey(pub)
		k.marshal = append([]byte(nil), blob[:r.off]...)
		// Re-marshal to canonical form for tag computation.
		k.marshal = marshalSSHPublicKey(k)
		return k, nil
	case "ssh-rsa":
		e, err := r.readMPInt()
		if err != nil {
			return nil, errors.New("ssh: no key found")
		}
		n, err := r.readMPInt()
		if err != nil || !e.IsInt64() {
			return nil, errors.New("ssh: no key found")
		}
		k := newSSHRSAPublicKey(&rsa.PublicKey{N: n, E: int(e.Int64())})
		return k, nil
	default:
		// Make a small attempt to reject completely bogus blobs for the
		// unsupported types that have a simple layout, but otherwise
		// treat the presence of a recognizable type string as a valid
		// (unsupported) SSH public key. This is only used to decide
		// whether to ignore the line in a recipients file.
		return &sshPublicKey{typ: typ, marshal: append([]byte(nil), blob...)}, nil
	}
}

func parseSSHAuthorizedKey(line string) (*sshPublicKey, error) {
	fields := strings.Fields(line)
	if len(fields) < 2 {
		return nil, errors.New("ssh: no key found")
	}
	blob, err := base64.StdEncoding.DecodeString(fields[1])
	if err != nil {
		return nil, fmt.Errorf("ssh: no key found; last parsing error for ignored line: %w", err)
	}
	pub, err := parseSSHPublicKeyBlob(blob)
	if err != nil {
		return nil, err
	}
	if pub.typ != fields[0] {
		return nil, errors.New("ssh: no key found")
	}
	return pub, nil
}

func sshRecipientFromPublic(pub *sshPublicKey) (Recipient, error) {
	switch pub.typ {
	case "ssh-rsa":
		if pub.rsa.N.BitLen() < 2048 {
			return nil, errors.New("RSA key size is too small")
		}
		return &SSHRSARecipient{pub: pub}, nil
	case "ssh-ed25519":
		if len(pub.ed) != 32 {
			return nil, errors.New("invalid Ed25519 public key")
		}
		return &SSHEd25519Recipient{pub: pub}, nil
	default:
		return nil, fmt.Errorf("unsupported SSH recipient type: %s", pub.typ)
	}
}

func parseSSHRecipient(s string) (Recipient, error) {
	pub, err := parseSSHAuthorizedKey(s)
	if err != nil {
		return nil, err
	}
	return sshRecipientFromPublic(pub)
}

var errSSHInvalidOpenSSH = errors.New("ssh: invalid openssh private key format")
var errSSHNoKeyFound = errors.New("ssh: no key found")
var errSSHIncorrectPassword = errors.New("x509: decryption password incorrect")

type sshPassphraseMissing struct {
	pub *sshPublicKey
}

func (e *sshPassphraseMissing) Error() string { return "ssh: passphrase missing" }

type openSSHParsed struct {
	priv interface{}
	pub  *sshPublicKey
}

func parseOpenSSHPrivateKey(data, passphrase []byte, havePass bool) (*openSSHParsed, error) {
	const magic = "openssh-key-v1\x00"
	if !bytes.HasPrefix(data, []byte(magic)) {
		return nil, errSSHInvalidOpenSSH
	}
	r := &wireReader{b: data, off: len(magic)}
	cipherName, err := r.readString()
	if err != nil {
		return nil, errSSHInvalidOpenSSH
	}
	kdfName, err := r.readString()
	if err != nil {
		return nil, errSSHInvalidOpenSSH
	}
	kdfOpts, err := r.readString()
	if err != nil {
		return nil, errSSHInvalidOpenSSH
	}
	nkeys, err := r.readUint32()
	if err != nil || nkeys < 1 {
		return nil, errSSHInvalidOpenSSH
	}
	var pubBlobs [][]byte
	for i := uint32(0); i < nkeys; i++ {
		b, err := r.readString()
		if err != nil {
			return nil, errSSHInvalidOpenSSH
		}
		pubBlobs = append(pubBlobs, b)
	}
	var pub *sshPublicKey
	if len(pubBlobs) > 0 {
		// Parse errors of the public blob only make it unusable for
		// matching; retain its raw type if possible.
		if p, err := parseSSHPublicKeyBlob(pubBlobs[0]); err == nil {
			pub = p
		}
	}
	encrypted, err := r.readString()
	if err != nil {
		return nil, errSSHInvalidOpenSSH
	}
	section := encrypted
	isEncrypted := !(string(cipherName) == "none" && string(kdfName) == "none")
	if isEncrypted {
		if !havePass {
			return &openSSHParsed{pub: pub}, &sshPassphraseMissing{pub: pub}
		}
		// Any remaining bytes after the encrypted string are an AEAD tag
		// for some ciphers; pass them along to the decryption helper by
		// re-appending them for those cases.
		rest := data[r.off:]
		section, err = decryptOpenSSHSection(string(cipherName), string(kdfName), kdfOpts, encrypted, rest, passphrase)
		if err != nil {
			return nil, err
		}
	}
	priv, err := parseOpenSSHPrivateSection(section, isEncrypted)
	if err != nil {
		return nil, err
	}
	return &openSSHParsed{priv: priv, pub: pub}, nil
}

func parseOpenSSHPrivateSection(section []byte, wasEncrypted bool) (interface{}, error) {
	invalid := func() (interface{}, error) {
		if wasEncrypted {
			return nil, errSSHIncorrectPassword
		}
		return nil, errSSHInvalidOpenSSH
	}
	r := &wireReader{b: section}
	check1, err := r.readUint32()
	if err != nil {
		return invalid()
	}
	check2, err := r.readUint32()
	if err != nil || check1 != check2 {
		return invalid()
	}
	typBytes, err := r.readString()
	if err != nil {
		return invalid()
	}
	typ := string(typBytes)
	switch typ {
	case "ssh-ed25519":
		pub, err := r.readString()
		if err != nil {
			return invalid()
		}
		priv, err := r.readString()
		if err != nil {
			return invalid()
		}
		if len(priv) == 64 {
			return ed25519.PrivateKey(priv), nil
		}
		if len(priv) == 32 {
			return ed25519.NewKeyFromSeed(priv), nil
		}
		_ = pub
		return invalid()
	case "ssh-rsa":
		n, err1 := r.readMPInt()
		eBig, err2 := r.readMPInt()
		d, err3 := r.readMPInt()
		iqmp, err4 := r.readMPInt()
		p, err5 := r.readMPInt()
		q, err6 := r.readMPInt()
		if err1 != nil || err2 != nil || err3 != nil || err4 != nil || err5 != nil || err6 != nil || !eBig.IsInt64() {
			return invalid()
		}
		priv := &rsa.PrivateKey{
			PublicKey: rsa.PublicKey{N: n, E: int(eBig.Int64())},
			D:         d,
			Primes:    []*big.Int{p, q},
		}
		priv.Precomputed.Dqinv = iqmp
		priv.Precompute()
		return priv, nil
	case "ecdsa-sha2-nistp256", "ecdsa-sha2-nistp384", "ecdsa-sha2-nistp521":
		curveName, err := r.readString()
		if err != nil {
			return invalid()
		}
		pub, err := r.readString()
		if err != nil {
			return invalid()
		}
		d, err := r.readMPInt()
		if err != nil {
			return invalid()
		}
		var curve elliptic.Curve
		switch string(curveName) {
		case "nistp256":
			curve = elliptic.P256()
		case "nistp384":
			curve = elliptic.P384()
		case "nistp521":
			curve = elliptic.P521()
		default:
			return invalid()
		}
		x, y := elliptic.Unmarshal(curve, pub)
		if x == nil {
			return invalid()
		}
		return &ecdsa.PrivateKey{PublicKey: ecdsa.PublicKey{Curve: curve, X: x, Y: y}, D: d}, nil
	case "ssh-dss":
		vals := make([]*big.Int, 6)
		for i := range vals {
			v, err := r.readMPInt()
			if err != nil {
				return invalid()
			}
			vals[i] = v
		}
		return &dsa.PrivateKey{PublicKey: dsa.PublicKey{Parameters: dsa.Parameters{P: vals[0], Q: vals[1], G: vals[2]}, Y: vals[3]}, X: vals[4]}, nil
	default:
		return nil, fmt.Errorf("ssh: unsupported key type %q", typ)
	}
}

func parsePEMPrivateKey(block *pem.Block, passphrase []byte, havePass bool) (interface{}, error) {
	if x509.IsEncryptedPEMBlock(block) {
		if !havePass {
			return nil, &sshPassphraseMissing{}
		}
		der, err := x509.DecryptPEMBlock(block, passphrase)
		if err != nil {
			return nil, err
		}
		// Parse the decrypted DER according to the block type.
		switch block.Type {
		case "RSA PRIVATE KEY":
			return x509.ParsePKCS1PrivateKey(der)
		case "EC PRIVATE KEY":
			return x509.ParseECPrivateKey(der)
		default:
			return x509.ParsePKCS8PrivateKey(der)
		}
	}
	switch block.Type {
	case "RSA PRIVATE KEY":
		return x509.ParsePKCS1PrivateKey(block.Bytes)
	case "PRIVATE KEY":
		return x509.ParsePKCS8PrivateKey(block.Bytes)
	case "EC PRIVATE KEY":
		return x509.ParseECPrivateKey(block.Bytes)
	case "ENCRYPTED PRIVATE KEY":
		if !havePass {
			return nil, &sshPassphraseMissing{}
		}
		return nil, errSSHIncorrectPassword
	default:
		return nil, fmt.Errorf("ssh: unsupported key type %q", block.Type)
	}
}

func parseSSHPrivateKeyBytes(contents, passphrase []byte, havePass bool) (interface{}, *sshPublicKey, error) {
	block, _ := pem.Decode(contents)
	if block == nil {
		return nil, nil, errSSHNoKeyFound
	}
	if block.Type == "OPENSSH PRIVATE KEY" {
		parsed, err := parseOpenSSHPrivateKey(block.Bytes, passphrase, havePass)
		if err != nil {
			if pm, ok := err.(*sshPassphraseMissing); ok {
				return nil, pm.pub, err
			}
			if parsed != nil {
				return nil, parsed.pub, err
			}
			return nil, nil, err
		}
		return parsed.priv, parsed.pub, nil
	}
	// For other PEM types, detect encrypted blocks before parsing so the
	// caller can look for a .pub file.
	if x509.IsEncryptedPEMBlock(block) || block.Type == "ENCRYPTED PRIVATE KEY" {
		if !havePass {
			return nil, nil, &sshPassphraseMissing{}
		}
	}
	// A block type other than the known private-key types reports an
	// unsupported key type even if its bytes are garbage.
	switch block.Type {
	case "RSA PRIVATE KEY", "PRIVATE KEY", "EC PRIVATE KEY", "ENCRYPTED PRIVATE KEY", "DSA PRIVATE KEY":
	default:
		return nil, nil, fmt.Errorf("ssh: unsupported key type %q", block.Type)
	}
	if block.Type == "DSA PRIVATE KEY" {
		return nil, nil, fmt.Errorf("ssh: unsupported key type %q", block.Type)
	}
	priv, err := parsePEMPrivateKey(block, passphrase, havePass)
	return priv, nil, err
}

func sshIdentityFromPrivateKey(name string, priv interface{}, pubHint *sshPublicKey) (Identity, *sshPublicKey, error) {
	switch k := priv.(type) {
	case *rsa.PrivateKey:
		pub := newSSHRSAPublicKey(&k.PublicKey)
		return &SSHRSAIdentity{priv: k, pub: pub}, pub, nil
	case ed25519.PrivateKey:
		pubBytes := append([]byte(nil), k.Public().(ed25519.PublicKey)...)
		pub := newSSHEd25519PublicKey(pubBytes)
		return &SSHEd25519Identity{seed: k.Seed(), pub: pub}, pub, nil
	default:
		return nil, nil, fmt.Errorf("unsupported SSH identity type: %T", priv)
	}
}

func sshRecipientForIdentity(id Identity) (Recipient, error) {
	switch v := id.(type) {
	case *SSHRSAIdentity:
		return &SSHRSARecipient{pub: v.pub}, nil
	case *SSHEd25519Identity:
		return &SSHEd25519Recipient{pub: v.pub}, nil
	case *EncryptedSSHIdentity:
		return sshRecipientFromPublic(v.pub)
	default:
		return nil, errors.New("unsupported SSH identity")
	}
}

type EncryptedSSHIdentity struct {
	name             string
	contents         []byte
	pub              *sshPublicKey
	passphraseFunc   func(name string) ([]byte, error)
	decrypted        Identity
}

func (id *EncryptedSSHIdentity) matches(stanzas []*Stanza) bool {
	for _, s := range stanzas {
		if s.Type != id.pub.typ {
			continue
		}
		if len(s.Args) < 1 {
			continue
		}
		tag, err := b64RawDecode(s.Args[0])
		if err != nil {
			continue
		}
		if bytesEqual(tag, id.pub.tag()) {
			return true
		}
	}
	return false
}

func (id *EncryptedSSHIdentity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	if !id.matches(stanzas) {
		return nil, errNoIdentityMatch
	}
	if id.decrypted == nil {
		pass, err := id.passphraseFunc(id.name)
		if err != nil {
			return nil, fmt.Errorf("failed to obtain passphrase: %w", err)
		}
		priv, _, err := parseSSHPrivateKeyBytes(id.contents, pass, true)
		if err != nil {
			return nil, fmt.Errorf("failed to decrypt SSH key file: %w", err)
		}
		realID, _, err := sshIdentityFromPrivateKey(id.name, priv, id.pub)
		if err != nil {
			return nil, fmt.Errorf("failed to decrypt SSH key file: %w", err)
		}
		id.decrypted = realID
	}
	return id.decrypted.Unwrap(stanzas)
}

// parseSSHIdentityFile parses an SSH private key file whose contents have
// already been read. It returns an Identity (possibly encrypted/lazy).
// The returned error does not include the outer `reading "name":` prefix;
// the caller adds it.
func parseSSHIdentityFile(name string, contents []byte, passphraseFunc func(string) ([]byte, error)) (Identity, error) {
	// Mirrors the reference tool: PEM-looking files that fail SSH parsing
	// are reported as malformed SSH identities, except for the
	// encrypted-key cases which are handled specially below.
	priv, pub, err := parseSSHPrivateKeyBytes(contents, nil, false)
	if err != nil {
		if _, ok := err.(*sshPassphraseMissing); ok {
			if pub == nil {
				// Try the adjacent .pub file.
				pubName := name + ".pub"
				pubContents, ferr := os.ReadFile(pubName)
				if ferr != nil {
					return nil, fmt.Errorf("failed to obtain public key for %q SSH key: %w\n\nEnsure %q exists, or convert the private key %q to a modern format with \"ssh-keygen -p -m RFC4716\"", name, ferr, pubName, name)
				}
				// Use the first line of the .pub file.
				line := strings.TrimSpace(string(pubContents))
				if idx := strings.IndexByte(line, '\n'); idx >= 0 {
					line = strings.TrimSpace(line[:idx])
				}
				p, perr := parseSSHAuthorizedKey(line)
				if perr != nil {
					return nil, fmt.Errorf("failed to obtain public key for %q SSH key: %w", name, perr)
				}
				pub = p
			}
			if pub.typ != "ssh-rsa" && pub.typ != "ssh-ed25519" {
				return nil, fmt.Errorf("unsupported SSH key type: %s", pub.typ)
			}
			return &EncryptedSSHIdentity{name: name, contents: append([]byte(nil), contents...), pub: pub, passphraseFunc: passphraseFunc}, nil
		}
		return nil, fmt.Errorf("malformed SSH identity in %q: %w", name, err)
	}
	id, _, err := sshIdentityFromPrivateKey(name, priv, pub)
	if err != nil {
		return nil, fmt.Errorf("malformed SSH identity in %q: %w", name, err)
	}
	return id, nil
}
