cat > openssh_cipher.go << 'EOF'
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/binary"
	"errors"
	"fmt"
)

func decryptOpenSSHSection(cipherName, kdfName string, kdfOpts, encrypted, rest, passphrase []byte) ([]byte, error) {
	if kdfName != "bcrypt" {
		return nil, fmt.Errorf("ssh: unknown KDF %q", kdfName)
	}
	r := &wireReader{b: kdfOpts}
	salt, err := r.readString()
	if err != nil {
		return nil, errSSHInvalidOpenSSH
	}
	rounds, err := r.readUint32()
	if err != nil {
		return nil, errSSHInvalidOpenSSH
	}
	var keyLen, ivLen int
	switch cipherName {
	case "aes128-ctr", "aes128-cbc":
		keyLen, ivLen = 16, 16
	case "aes192-ctr", "aes192-cbc":
		keyLen, ivLen = 24, 16
	case "aes256-ctr", "aes256-cbc":
		keyLen, ivLen = 32, 16
	case "aes128-gcm@openssh.com":
		keyLen, ivLen = 16, 12
	case "aes256-gcm@openssh.com":
		keyLen, ivLen = 32, 12
	default:
		return nil, fmt.Errorf("ssh: unknown cipher %q", cipherName)
	}
	keyIV, err := bcryptPbkdf(passphrase, salt, int(rounds), keyLen+ivLen)
	if err != nil {
		return nil, err
	}
	key, iv := keyIV[:keyLen], keyIV[keyLen:]
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	out := make([]byte, len(encrypted))
	switch cipherName {
	case "aes128-ctr", "aes192-ctr", "aes256-ctr":
		cipher.NewCTR(block, iv).XORKeyStream(out, encrypted)
		return out, nil
	case "aes128-cbc", "aes192-cbc", "aes256-cbc":
		if len(encrypted)%aes.BlockSize != 0 {
			return nil, errSSHInvalidOpenSSH
		}
		cipher.NewCBCDecrypter(block, iv).CryptBlocks(out, encrypted)
		return out, nil
	case "aes128-gcm@openssh.com", "aes256-gcm@openssh.com":
		gcm, err := cipher.NewGCM(block)
		if err != nil {
			return nil, err
		}
		tag := rest
		if len(tag) < 16 {
			return nil, errSSHIncorrectPassword
		}
		ct := append(append([]byte(nil), encrypted...), tag[:16]...)
		pt, err := gcm.Open(nil, iv, ct, nil)
		if err != nil {
			return nil, errSSHIncorrectPassword
		}
		return pt, nil
	}
	_ = binary.BigEndian
	return nil, errors.New("unsupported cipher")
}
