{"command":"cat > term.go << 'EOF'
package main

import (
	"fmt"
	"io"
	"os"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

const (
	tiocGet = syscall.TCGETS
	tiocSet = 0x5402 // TCSETS on Linux/amd64 (and most Linux archs supported here)
)

func ioctlTermios(fd uintptr, request uintptr, termios *syscall.Termios) error {
	_, _, errno := syscall.Syscall6(syscall.SYS_IOCTL, fd, request, uintptr(unsafe.Pointer(termios)), 0, 0, 0)
	if errno != 0 {
		return errno
	}
	return nil
}

func isTerminal(fd uintptr) bool {
	var t syscall.Termios
	return ioctlTermios(fd, tiocGet, &t) == nil
}

type ttyHandle struct {
	f       *os.File
	ownFile bool
}

func openTTY() (*ttyHandle, error) {
	if isTerminal(os.Stdin.Fd()) {
		return &ttyHandle{f: os.Stdin}, nil
	}
	f, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, fmt.Errorf("standard input is not a terminal, and /dev/tty is not available: %w", err)
	}
	return &ttyHandle{f: f, ownFile: true}, nil
}

func (t *ttyHandle) Close() {
	if t.ownFile {
		t.f.Close()
	}
}

const (
	tcECHO    = 0x0008
	tcICANON  = 0x0002
	tcISIG    = 0x0001
	tcIEXTEN  = 0x8000
	tcICRNL   = 0x0100
	tcIXON    = 0x0400
	tcOPOST   = 0x0001
)

func readSecret(prompt string) ([]byte, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, err
	}
	defer tty.Close()
	return tty.readSecret(prompt)
}

func (t *ttyHandle) readSecret(prompt string) ([]byte, error) {
	fd := t.f.Fd()
	var old syscall.Termios
	if err := ioctlTermios(fd, tiocGet, &old); err != nil {
		return nil, err
	}
	if _, err := fmt.Fprintf(t.f, "%s ", prompt); err != nil {
		return nil, err
	}
	newState := old
	newState.Lflag &^= tcECHO
	newState.Lflag |= tcICANON | tcISIG
	newState.Iflag |= tcICRNL
	if err := ioctlTermios(fd, tiocSet, &newState); err != nil {
		return nil, err
	}
	defer ioctlTermios(fd, tiocSet, &old)
	defer func() {
		// Move to a new line and erase the prompt line, matching the
		// reference UI. The string is written literally; the terminal
