	}()
	var ret []byte
	var buf [1]byte
	for {
		n, err := t.f.Read(buf[:])
		if n > 0 {
			switch buf[0] {
			case '\b', 0x7f:
				if len(ret) > 0 {
					ret = ret[:len(ret)-1]
				}
			case '\n', '\r':
				return ret, nil
			default:
				ret = append(ret, buf[0])
			}
		}
		if err != nil {
			if err == io.EOF && len(ret) > 0 {
				return ret, nil
			}
			return nil, err
		}
	}
}

func readPublic(prompt string) ([]byte, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, err
	}
	defer tty.Close()
	return tty.readPublic(prompt)
}

func (t *ttyHandle) readPublic(prompt string) ([]byte, error) {
	fd := t.f.Fd()
	var old syscall.Termios
	if err := ioctlTermios(fd, tiocGet, &old); err != nil {
		return nil, err
	}
	if _, err := fmt.Fprintf(t.f, "%s ", prompt); err != nil {
		return nil, err
	}
	// A small line editor in raw mode, enough for ordinary prompts:
	// printable input is echoed, backspace deletes, Ctrl-C/Ctrl-D
	// cancel with EOF, and Ctrl-U clears the line.
	newState := old
	newState.Iflag &^= 0x0001 | 0x0002 | 0x0010 | 0x0100 // BRKINT, ICRNL, INPCK, ISTRIP-ish; keep byte stream simple
	newState.Iflag &^= tcIXON
	newState.Lflag &^= tcECHO | tcICANON | tcIEXTEN | tcISIG
	newState.Cflag |= 0x0030 // CS8
	newState.Cc[6] = 1       // VMIN
	newState.Cc[5] = 0       // VTIME
	if err := ioctlTermios(fd, tiocSet, &newState); err != nil {
		return nil, err
	}
	defer ioctlTermios(fd, tiocSet, &old)
	defer func() {
		_, _ = t.f.WriteString("\r\n\x1b[F\x1b[K")
	}()
	var ret []byte
	var inbuf [1]byte
	var pending []byte // bytes of an incomplete UTF-8 sequence being typed
	eraseLastRune := func() {
		if len(ret) == 0 {
			return
		}
		_, size := utf8.DecodeLastRune(ret)
		if size <= 0 {
			size = 1
		}
		ret = ret[:len(ret)-size]
		_, _ = t.f.WriteString("\b \b")
	}
	for {
		n, err := t.f.Read(inbuf[:])
		if n > 0 {
			b := inbuf[0]
			switch b {
			case '\n', '\r':
				return ret, nil
			case 3: // Ctrl-C
				return nil, io.EOF
			case 4: // Ctrl-D
				if len(ret) == 0 {
					return nil, io.EOF
				}
			case '\b', 0x7f:
				eraseLastRune()
			case 21: // Ctrl-U
				for len(ret) > 0 {
					eraseLastRune()
				}
			case 27: // Escape: swallow a following CSI sequence if present.
				// Best-effort: read up to a final byte in @-~ range.
				// Terminal is in raw mode, these reads can see the
				// rest of an arrow key sequence.
				// (If it's a lone ESC from a paste, the following
				// characters are consumed; acceptable for a prompt.)
				for i := 0; i < 8; i++ {
					var eb [1]byte
					if _, e := t.f.Read(eb[:]); e != nil {
						break
					}
					if eb[0] >= 0x40 && eb[0] <= 0x7e {
						break
					}
				}
			default:
				if b < 0x20 {
					break
				}
				pending = append(pending, b)
				if utf8.FullRune(pending) {
					ret = append(ret, pending...)
					_, _ = t.f.Write(pending)
					pending = pending[:0]
				}
			}
		}
		if err != nil {
			if err == io.EOF && len(ret) > 0 {
				return ret, nil
			}
			return nil, err
		}
	}
}

// readPassphrase is the passphrase callback error-wrapping layer used by
// the command for native passphrase prompts.
func readPassphrase(prompt string) ([]byte, error) {
	p, err := readSecret(prompt)
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: %w", err)
	}
	return p, nil
}
