func (c *pluginConn) readResults(mode string) (*pluginResults, error) {
	res := &pluginResults{fileKeys: make(map[int][]byte)}
	for {
		st, err := c.readStanza()
		if err != nil {
			c.close()
			return nil, err
		}
		switch st.Type {
		case "done":
			c.close()
