	}
	commands := []*Stanza{
		{Type: "add-recipient", Args: []string{r.encoding}},
		{Type: "wrap-file-key", Body: append([]byte(nil), fileKey...)},
		{Type: "extension-labels"},
		{Type: "done"},
	}
	if err := conn.sendInitial(commands); err != nil {
		conn.close()
		return nil, nil, err
	}
	res, err := conn.readResults("recipient")
	if err != nil {
