func (id *pluginIdentity) Wrap(fileKey []byte) ([]*Stanza, []string, error) {
	conn, err := startPlugin(id.name, "recipient-v1")
	if err != nil {
		return nil, nil, err
	}
	commands := []*Stanza{
		{Type: "add-identity", Args: []string{id.encoding}},
		{Type: "wrap-file-key", Body: append([]byte(nil), fileKey...)},
		{Type: "extension-labels"},
		{Type: "done"},
	}
