		conn.close()
		return nil, nil, err
	}
	res, err := conn.readResults("recipient")
	if err != nil {
		return nil, nil, err
	}
	if res.err != nil {
		return nil, nil, &pluginError{name: id.name, msg: res.err.Error(), raw: true}
	}
	if len(res.recipientStanzas) == 0 {
		return nil, nil, &pluginError{name: id.name, msg: "received zero recipient stanzas", raw: true}
	}
	return res.recipientStanzas, res.labels, nil
}

func (id *pluginIdentity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	conn, err := startPlugin(id.name, "identity-v1")
	if err != nil {
		return nil, err
	}
	commands := []*Stanza{{Type: "add-identity", Args: []string{id.encoding}}}
	for i, s := range stanzas {
		args := []string{strconv.Itoa(i), s.Type}
		args = append(args, s.Args...)
		commands = append(commands, &Stanza{Type: "recipient-stanza", Args: args, Body: append([]byte(nil), s.Body...)})
	}
	commands = append(commands, &Stanza{Type: "done"})
	if err := conn.sendInitial(commands); err != nil {
		conn.close()
		return nil, err
	}
	res, err := conn.readResults("identity")
	if err != nil {
		return nil, err
	}
	for idx := range stanzas {
		if fk, ok := res.fileKeys[idx]; ok {
			return fk, nil
		}
	}
	if len(res.fileKeys) > 0 {
		// A file key for an out-of-range index is not usable.
		return nil, errNoIdentityMatch
	}
	if res.err != nil {
		// Errors scoped to a particular recipient stanza are treated as
		// that stanza not matching; unscoped errors are reported.
		if len(res.errArgs) == 0 {
			return nil, &pluginError{name: id.name, msg: res.err.Error(), raw: true}
		}
		return nil, errNoIdentityMatch
	}
	return nil, errNoIdentityMatch
}
