func validPluginName(name string) bool {
	if name == "" {
		return false
	}
	if strings.Contains(name, "/") || strings.Contains(name, "\\") {
		return false
	}
	for _, r := range name {
		if r <= ' ' || r == 0x7f {
			return false
		}
	}
	return true
}

type pluginNotFoundError struct {
	name string
	err  error
}

func (e *pluginNotFoundError) Error() string {
	return fmt.Sprintf("%s plugin: couldn't start plugin: %q plugin not found: %v", e.name, e.name, e.err)
}
func (e *pluginNotFoundError) Unwrap() error { return e.err }

type pluginError struct {
	name string
	err  error
	msg  string
	raw  bool // msg is the full message after "<name> plugin: "
}

func (e *pluginError) Error() string {
	if e.raw {
		return fmt.Sprintf("%s plugin: %s", e.name, e.msg)
	}
	return fmt.Sprintf("%s plugin: %v", e.name, e.err)
}

type pluginConn struct {
	name    string
	cmd     *exec.Cmd
	stdin   io.WriteCloser
	bw      *bufio.Writer
	sr      *stanzaReader
	debug   bool
	waited  bool
}

func startPlugin(name, phase string) (*pluginConn, error) {
	binaryName := "age-plugin-" + name
	cmd := exec.Command(binaryName, "--age-plugin="+phase)
	// exec.Command with a name containing no separator performs a PATH
	// lookup when Start is called, matching reference error strings.
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return nil, &pluginError{name: name, err: fmt.Errorf("couldn't start plugin: %w", err), raw: false}
	}
	stdout, err := cmd.StdoutPipe()
	if err != nil {
		return nil, &pluginError{name: name, err: fmt.Errorf("couldn't start plugin: %w", err)}
	}
	// Stderr is left nil, so the child is connected to the null device.
	if err := cmd.Start(); err != nil {
		if errors.Is(err, exec.ErrNotFound) {
			return nil, &pluginNotFoundError{name: name, err: err}
		}
		return nil, &pluginError{name: name, msg: fmt.Sprintf("couldn't start plugin: %v", err), raw: true}
	}
	return &pluginConn{
		name:  name,
		cmd:   cmd,
		stdin: stdin,
		bw:    bufio.NewWriter(stdin),
		sr:    &stanzaReader{lr: &lineReader{r: bufio.NewReader(stdout)}},
		debug: os.Getenv("AGEDEBUG") == "plugin",
	}, nil
}

func (c *pluginConn) logStanza(s *Stanza) {
	if c.debug {
		_, _ = os.Stderr.Write(s.marshal())
	}
}

func (c *pluginConn) sendStanza(s *Stanza) error {
	c.logStanza(s)
	if _, err := c.bw.Write(s.marshal()); err != nil {
		return err
	}
	return c.bw.Flush()
}

func greaseStanza() *Stanza {
	// Random grease exercises extensibility handling in plugins.
	var rnd [8]byte
	_, _ = randRead(rnd[:])
	v := uint64(rnd[0]) | uint64(rnd[1])<<8 | uint64(rnd[2])<<16 | uint64(rnd[3])<<24 |
		uint64(rnd[4])<<32 | uint64(rnd[5])<<40 | uint64(rnd[6])<<48 | uint64(rnd[7])<<56
	st := &Stanza{Type: fmt.Sprintf("grease-%x", v)}
	nArgs := randIntn(3)
	for i := 0; i < nArgs; i++ {
		st.Args = append(st.Args, strconv.Itoa(randIntn(100)))
	}
	bodyLen := randIntn(91)
	if bodyLen > 0 {
		st.Body = make([]byte, bodyLen)
		_, _ = randRead(st.Body)
	}
	return st
}

func (c *pluginConn) sendInitial(stanzas []*Stanza) error {
	for i, s := range stanzas {
		if err := c.sendStanza(s); err != nil {
			return c.wrapErr(err)
		}
		if i == 0 && randIntn(2) == 0 {
			// Roughly half of connections include a grease stanza
			// immediately after the first command.
			if err := c.sendStanza(greaseStanza()); err != nil {
				return c.wrapErr(err)
			}
		}
	}
	return nil
}

func (c *pluginConn) wrapErr(err error) error {
	if err == nil {
		return nil
	}
	var nf *pluginNotFoundError
	if errors.As(err, &nf) {
		return err
	}
	var pe *pluginError
	if errors.As(err, &pe) {
		return err
	}
	return &pluginError{name: c.name, err: err}
}

func (c *pluginConn) readStanza() (*Stanza, error) {
	st, err := c.sr.readStanza()
	if err != nil {
		if err == io.EOF {
			return nil, &pluginError{name: c.name, msg: "failed to read line: EOF", raw: true}
		}
		return nil, c.wrapErr(err)
	}
	c.logStanza(st)
	return st, nil
}

func (c *pluginConn) respond(typ string, body []byte) error {
	s := &Stanza{Type: typ, Body: append([]byte(nil), body...)}
	return c.sendStanza(s)
}

func (c *pluginConn) close() {
	if c.cmd == nil || c.waited {
		return
	}
	c.waited = true
	_ = c.bw.Flush()
	_ = c.stdin.Close()
	done := make(chan struct{})
	go func() {
		_ = c.cmd.Wait()
		close(done)
	}()
	select {
	case <-done:
		return
	case <-time.After(200 * time.Millisecond):
	}
	if c.cmd.Process != nil {
		_ = c.cmd.Process.Signal(os.Interrupt)
	}
	select {
	case <-done:
		return
	case <-time.After(time.Second):
	}
	if c.cmd.Process != nil {
		_ = c.cmd.Process.Kill()
		<-done
	}
}

type pluginResults struct {
	recipientStanzas []*Stanza
	fileKeys         map[int][]byte
	labels           []string
	err              error // plugin-reported error, without the wrapper prefix
	errArgs          []string
}

func (c *pluginConn) readResults(mode string) (*pluginResults, error) {
	res := &pluginResults{fileKeys: make(map[int][]byte)}
	for {
		st, err := c.readStanza()
		if err != nil {
			c.close()
			return nil, err
		}
		switch st.Type {
		case "done":
			c.close()
			return res, nil
		case "recipient-stanza":
			if mode != "recipient" {
				_ = c.respond("unsupported", nil)
				continue
			}
			if len(st.Args) < 2 {
				_ = c.respond("fail", nil)
				continue
			}
			rs := &Stanza{Type: st.Args[1], Args: append([]string(nil), st.Args[2:]...), Body: append([]byte(nil), st.Body...)}
			res.recipientStanzas = append(res.recipientStanzas, rs)
			_ = c.respond("ok", nil)
		case "file-key":
			if mode != "identity" {
				_ = c.respond("unsupported", nil)
				continue
			}
			if len(st.Args) != 1 {
				_ = c.respond("fail", nil)
				continue
			}
			idx, err := strconv.Atoi(st.Args[0])
			if err != nil {
				_ = c.respond("fail", nil)
				continue
			}
			res.fileKeys[idx] = append([]byte(nil), st.Body...)
			_ = c.respond("ok", nil)
		case "labels":
			if mode != "recipient" {
				_ = c.respond("unsupported", nil)
				continue
			}
			res.labels = append([]string(nil), st.Args...)
			_ = c.respond("ok", nil)
		case "msg":
			logPrintf("%s plugin: %s", c.name, string(st.Body))
			_ = c.respond("ok", nil)
		case "request-secret":
			v, err := readSecret(string(st.Body))
			if err != nil {
				logPrintf("warning: could not read value for age-plugin-%s: %v", c.name, err)
				_ = c.respond("fail", nil)
			} else {
				_ = c.respond("ok", v)
			}
		case "request-public":
			v, err := readPublic(string(st.Body))
			if err != nil {
				logPrintf("warning: could not read value for age-plugin-%s: %v", c.name, err)
				_ = c.respond("fail", nil)
			} else {
				_ = c.respond("ok", v)
			}
		case "error":
			res.err = errors.New(string(st.Body))
			res.errArgs = append([]string(nil), st.Args...)
			_ = c.respond("ok", nil)
		default:
			_ = c.respond("unsupported", nil)
		}
	}
}

// randRead and randIntn are tiny wrappers so grease generation uses the
// cryptographic RNG without importing crypto/rand under two names in
// files that also need a deterministic PRNG interface.
func randRead(b []byte) (int, error) {
	return io.ReadFull(cryptoRandReader{}, b)
}

type cryptoRandReader struct{}

func (cryptoRandReader) Read(p []byte) (int, error) { return cryptoRandRead(p) }

func randIntn(n int) int {
	var b [1]byte
	_, _ = randRead(b[:])
	return int(b[0]) % n
}

