func parsePluginRecipient(s string) (*pluginRecipient, error) {
	hrp, _, err := bech32Decode(s)
	if err != nil {
		return nil, fmt.Errorf("invalid recipient encoding: %w", err)
	}
	if !strings.HasPrefix(hrp, "age1") {
		return nil, fmt.Errorf("invalid recipient encoding: invalid human-readable prefix %q", hrp)
	}
	name := strings.TrimPrefix(hrp, "age1")
	if !validPluginName(name) {
		return nil, fmt.Errorf("invalid plugin name: %q", name)
	}
	return &pluginRecipient{name: name, encoding: s}, nil
}

func (r *pluginRecipient) Wrap(fileKey []byte) ([]*Stanza, []string, error) {
	conn, err := startPlugin(r.name, "recipient-v1")
	if err != nil {
		return nil, nil, err
	}
	commands := []*Stanza{
		{Type: "add-recipient", Args: []string{r.encoding}},
		{Type: "wrap-file-key", Body: append([]byte(nil), fileKey...)},
		{Type: "extension-labels"},
		{Type: "done"},
	}
	if err := conn.sendInitial(commands); err != nil {
		conn.close()
		return nil, nil, err
