	if res.err != nil {
		return nil, nil, &pluginError{name: r.name, msg: res.err.Error(), raw: true}
	}
	if len(res.recipientStanzas) == 0 {
		return nil, nil, &pluginError{name: r.name, msg: "received zero recipient stanzas", raw: true}
	}
	return res.recipientStanzas, res.labels, nil
}

func pluginIdentityEncoding(name string, data []byte) (string, error) {
	return bech32EncodeUpper("age-plugin-"+name+"-", data)
}

func newPluginIdentity(name string) (*pluginIdentity, error) {
	if !validPluginName(name) {
		return nil, fmt.Errorf("invalid plugin name: %q", name)
	}
	enc, err := pluginIdentityEncoding(name, nil)
	if err != nil {
		return nil, err
	}
	return &pluginIdentity{name: name, encoding: enc}, nil
}

func parsePluginIdentity(s string) (*pluginIdentity, error) {
	hrp, _, err := bech32Decode(s)
	if err != nil {
		return nil, err
	}
	if !strings.HasPrefix(hrp, "age-plugin-") || !strings.HasSuffix(hrp, "-") {
		return nil, errors.New("invalid plugin identity encoding")
	}
	name := strings.TrimSuffix(strings.TrimPrefix(hrp, "age-plugin-"), "-")
	if !validPluginName(name) {
		return nil, fmt.Errorf("invalid plugin name: %q", name)
	}
	return &pluginIdentity{name: name, encoding: s}, nil
}

func (id *pluginIdentity) Wrap(fileKey []byte) ([]*Stanza, []string, error) {
	conn, err := startPlugin(id.name, "recipient-v1")
	if err != nil {
		return nil, nil, err
	}
	commands := []*Stanza{
		{Type: "add-identity", Args: []string{id.encoding}},
		{Type: "wrap-file-key", Body: append([]byte(nil), fileKey...)},
