func (id *pluginIdentity) Unwrap(stanzas []*Stanza) ([]byte, error) {
	conn, err := startPlugin(id.name, "identity-v1")
	if err != nil {
		return nil, err
	}
	commands := []*Stanza{{Type: "add-identity", Args: []string{id.encoding}}}
	for i, s := range stanzas {
		args := []string{strconv.Itoa(i), s.Type}
		args = append(args, s.Args...)
		commands = append(commands, &Stanza{Type: "recipient-stanza", Args: args, Body: append([]byte(nil), s.Body...)})
	}
	commands = append(commands, &Stanza{Type: "done"})
	if err := conn.sendInitial(commands); err != nil {
		conn.close()
		return nil, err
	}
	res, err := conn.readResults("identity")
	if err != nil {
