    $ age --decrypt -i key.txt -o data.tar.gz data.tar.gz.age
`

type userError struct {
	msg   string
	hints []string
}

func (e *userError) Error() string { return e.msg }
func userErr(msg string, hints ...string) error { return &userError{msg: msg, hints: hints} }
func userErrf(format string, args ...interface{}) error { return &userError{msg: fmt.Sprintf(format, args...)} }

type multiString []string

func (m *multiString) String() string { return "" }
func (m *multiString) Set(v string) error {
	*m = append(*m, v)
	return nil
}

type identitySpec struct {
	plugin bool
	value  string
}
type identityFlagValue struct {
	specs  *[]identitySpec
	plugin bool
}

func (v *identityFlagValue) String() string { return "" }
func (v *identityFlagValue) Set(s string) error {
	*v.specs = append(*v.specs, identitySpec{plugin: v.plugin, value: s})
	return nil
}

var (
	flagEncrypt, flagDecrypt, flagArmor, flagPassphrase, flagVersion bool
	flagOutput                                                        string
	flagRecipients, flagRecipientsFile                                multiString
	flagIdentities                                                    []identitySpec
)

func main() {
	if len(os.Args) == 1 {
		fmt.Fprint(os.Stderr, usageText)
		os.Exit(1)
	}
	flag.Usage = func() { fmt.Fprint(flag.CommandLine.Output(), usageText) }
	flag.BoolVar(&flagEncrypt, "e", false, "")
	flag.BoolVar(&flagEncrypt, "encrypt", false, "")
	flag.BoolVar(&flagDecrypt, "d", false, "")
	flag.BoolVar(&flagDecrypt, "decrypt", false, "")
	flag.BoolVar(&flagArmor, "a", false, "")
	flag.BoolVar(&flagArmor, "armor", false, "")
	flag.BoolVar(&flagPassphrase, "p", false, "")
	flag.BoolVar(&flagPassphrase, "passphrase", false, "")
	flag.BoolVar(&flagVersion, "version", false, "")
	flag.StringVar(&flagOutput, "o", "", "")
	flag.StringVar(&flagOutput, "output", "", "")
	flag.Var(&flagRecipients, "r", "")
	flag.Var(&flagRecipients, "recipient", "")
	flag.Var(&flagRecipientsFile, "R", "")
	flag.Var(&flagRecipientsFile, "recipients-file", "")
	idFile := &identityFlagValue{specs: &flagIdentities, plugin: false}
	flag.Var(idFile, "i", "")
	flag.Var(idFile, "identity", "")
	flag.Var(&identityFlagValue{specs: &flagIdentities, plugin: true}, "j", "")
	flag.Parse()
	if flagVersion {
		fmt.Println(toolVersion)
		return
	}
	if err := run(); err != nil {
		printError(err)
		os.Exit(1)
	}
}

func printError(err error) {
	var nf *pluginNotFoundError
	if errors.Is(err, errCRLFIntro) {
		fmt.Fprintf(os.Stderr, "age: error: invalid header intro\n")
		fmt.Fprintf(os.Stderr, "age: hint: it looks like this file was corrupted by PowerShell redirection\n")
		fmt.Fprintf(os.Stderr, "age: hint: consider using -o or -a to encrypt files in PowerShell\n")
		fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
		return
	}
	var ue *userError
	if errors.As(err, &ue) {
		fmt.Fprintf(os.Stderr, "age: error: %s\n", ue.msg)
		for _, h := range ue.hints {
			fmt.Fprintf(os.Stderr, "age: hint: %s\n", h)
		}
	} else {
		fmt.Fprintf(os.Stderr, "age: error: %s\n", err.Error())
	}
	if errors.As(err, &nf) {
		fmt.Fprintf(os.Stderr, "age: hint: you might want to install the %q plugin\n", nf.name)
		fmt.Fprintf(os.Stderr, "age: hint: visit https://age-encryption.org/awesome#plugins for a list of available plugins\n")
	}
	fmt.Fprintf(os.Stderr, "age: report unexpected or unhelpful errors at https://filippo.io/age/report\n")
}

func warnDuplicates(values []string, kind string) {
	seen := make(map[string]bool)
	warned := make(map[string]bool)
	for _, v := range values {
		if seen[v] && !warned[v] {
			warnf("duplicate %s %q", kind, v)
			warned[v] = true
		}
		seen[v] = true
	}
}

func run() error {
	if flag.NArg() > 1 {
		args := flag.Args()
		quoted := make([]string, len(args))
		for i, a := range args {
			quoted[i] = fmt.Sprintf("%q", a)
		}
		return userErr(fmt.Sprintf("too many INPUT arguments: %s", strings.Join(quoted, " ")), "only a single input file may be specified at a time")
	}
	// Validation, in the reference tool's order.
	if flagEncrypt && flagDecrypt {
		return userErr("-e/--encrypt can't be used with -d/--decrypt")
	}
	if flagDecrypt {
		if flagArmor {
			return userErr("-a/--armor can't be used with -d/--decrypt", "note that armored files are detected automatically, try again without -a/--armor")
		}
		if flagPassphrase {
			return userErr("-p/--passphrase can't be used with -d/--decrypt", "note that password protected files are detected automatically")
		}
		if len(flagRecipients) > 0 {
			return userErr("-r/--recipient can't be used with -d/--decrypt", "did you mean to use -i/--identity to specify a private key?")
		}
		if len(flagRecipientsFile) > 0 {
			return userErr("-R/--recipients-file can't be used with -d/--decrypt", "did you mean to use -i/--identity to specify a private key?")
		}
	} else {
		if len(flagIdentities) > 0 && !flagEncrypt {
			return userErr("-i/--identity and -j can't be used in encryption mode unless symmetric encryption is explicitly selected with -e/--encrypt", "did you forget to specify -d/--decrypt?")
		}
		if flagPassphrase {
			if len(flagRecipients) > 0 {
				return userErr("-p/--passphrase can't be combined with -r/--recipient")
			}
			if len(flagRecipientsFile) > 0 {
				return userErr("-p/--passphrase can't be combined with -R/--recipients-file")
			}
			if len(flagIdentities) > 0 {
				return userErr("-p/--passphrase can't be combined with -i/--identity and -j")
			}
		} else if len(flagRecipients) == 0 && len(flagRecipientsFile) == 0 && len(flagIdentities) == 0 {
			return userErr("missing recipients", "did you forget to specify -r/--recipient, -R/--recipients-file or -p/--passphrase?")
		}
	}
	warnDuplicates(flagRecipients, "recipient")
	warnDuplicates(flagRecipientsFile, "recipients file")
	{
		var idFiles []string
		for _, s := range flagIdentities {
			if !s.plugin {
				idFiles = append(idFiles, s.value)
			}
		}
		warnDuplicates(idFiles, "identity file")
	}

	inputName := ""
	if flag.NArg() == 1 {
		inputName = flag.Arg(0)
	}
	in, err := openInput(inputName)
	if err != nil {
		return err
	}
	if in.file != nil {
		defer in.file.Close()
	}
	out, err := setupOutput(inputName)
	if err != nil {
		return err
	}
	if flagDecrypt {
		return decryptFile(in, out)
	}
	return encryptFile(in, out)
}

type inputFile struct {
	r         io.Reader
	file      *os.File
	fromStdin bool
	name      string
}

var stdinTaken bool

func openInput(name string) (*inputFile, error) {
	if name == "" || name == "-" {
		stdinTaken = true
		return &inputFile{r: os.Stdin, fromStdin: true, name: name}, nil
	}
	f, err := os.Open(name)
	if err != nil {
		return nil, userErrf("failed to open input file %q: %v", name, err)
	}
	return &inputFile{r: f, file: f, name: name}, nil
}

type lazyFileWriter struct {
	name    string
	f       *os.File
	tried   bool
	openErr error
}

func (w *lazyFileWriter) Write(p []byte) (int, error) {
	if w.f == nil {
		if w.tried {
			return 0, w.openErr
		}
		w.tried = true
		f, err := os.Create(w.name)
		if err != nil {
			w.openErr = err
			return 0, err
		}
		w.f = f
	}
	return w.f.Write(p)
}
func (w *lazyFileWriter) Close() error {
	if w.f == nil {
		if w.tried {
			return w.openErr
		}
		w.tried = true
		f, err := os.Create(w.name)
		if err != nil {
			w.openErr = err
			return err
		}
		w.f = f
	}
	return w.f.Close()
}

type outputWriter struct {
	w      io.Writer
	closer io.Closer // lazy file, if any
}

func (o *outputWriter) Write(p []byte) (int, error) { return o.w.Write(p) }
func (o *outputWriter) Close() error {
	if o.closer != nil {
		return o.closer.Close()
	}
	return nil
}

func setupOutput(inputName string) (*outputWriter, error) {
	if flagOutput == "" {
		if !flagDecrypt && !flagArmor && isTerminal(os.Stdout.Fd()) {
			return nil, userErr("refusing to output binary to the terminal", "did you mean to use -a/--armor?", "force anyway with \"-o -\"")
		}
		return &outputWriter{w: os.Stdout}, nil
	}
	if flagOutput == "-" {
		return &outputWriter{w: os.Stdout}, nil
	}
	absOut, err := filepath.Abs(flagOutput)
	if err == nil {
		var paths []string
		if inputName != "" {
			paths = append(paths, inputName)
		}
		paths = append(paths, flagRecipientsFile...)
		for _, s := range flagIdentities {
			if !s.plugin {
				paths = append(paths, s.value)
			}
		}
		for _, pth := range paths {
			if pth == "-" || pth == "" {
				continue
			}
			if absIn, err := filepath.Abs(pth); err == nil && absIn == absOut {
				return nil, userErrf("input and output file are the same: %q", flagOutput)
			}
		}
	}
	lw := &lazyFileWriter{name: flagOutput}
	return &outputWriter{w: lw, closer: lw}, nil
}

func readStdinOnce() ([]byte, error) {
	if stdinTaken {
		return nil, errors.New("standard input is used for multiple purposes")
	}
	stdinTaken = true
	return io.ReadAll(os.Stdin)
}

// ----- recipients -----

func parseRecipient(s string) (Recipient, error) {
	switch {
	case strings.HasPrefix(s, "age1pq1"):
		r, err := parsePQRecipient(s)
		if err != nil {
			return nil, fmt.Errorf("malformed recipient %q: %w", s, err)
		}
		return r, nil
	case strings.HasPrefix(s, "age1tagpq1"):
		r, err := parseTagPQRecipient(s)
		if err != nil {
			return nil, fmt.Errorf("malformed recipient %q: %w", s, err)
		}
		return r, nil
	case strings.HasPrefix(s, "age1tag1"):
		r, err := parseTagRecipient(s)
		if err != nil {
			return nil, fmt.Errorf("malformed recipient %q: %w", s, err)
		}
		return r, nil
	case strings.HasPrefix(s, "age1"):
		if strings.LastIndexByte(s, '1') != 3 {
			return parsePluginRecipient(s)
		}
		r, err := parseX25519Recipient(s)
		if err != nil {
			return nil, fmt.Errorf("malformed recipient %q: %w", s, err)
		}
		return r, nil
	case strings.HasPrefix(s, "ssh-"):
		r, err := parseSSHRecipient(s)
		if err != nil {
			return nil, fmt.Errorf("malformed SSH recipient: %q: %w", s, err)
		}
		return r, nil
	default:
		return nil, fmt.Errorf("unknown recipient type: %q", s)
	}
}

func splitLines(contents []byte) []string {
	s := string(contents)
	lines := strings.Split(s, "\n")
	for i := range lines {
		lines[i] = strings.TrimSuffix(lines[i], "\r")
	}
	if len(lines) > 0 && lines[len(lines)-1] == "" && strings.HasSuffix(s, "\n") {
		// The trailing empty element represents the final newline; keep
		// it as an empty line for line-number parity in most cases, but
		// dropping it avoids a phantom extra line when reporting
		// errors at EOF. Empty lines are skipped anyway.
		lines = lines[:len(lines)-1]
	}
	return lines
}

func parseRecipientsFile(name string) ([]Recipient, error) {
	var contents []byte
	if name == "-" {
		b, err := readStdinOnce()
		if err != nil {
			return nil, err
		}
		contents = b
	} else {
		f, err := os.Open(name)
		if err != nil {
			return nil, fmt.Errorf("failed to open recipient file: %w", err)
		}
		b, err := io.ReadAll(f)
		f.Close()
		if err != nil {
			return nil, fmt.Errorf("%q: failed to read recipients file: %w", name, err)
		}
		contents = b
	}
	var recipients []Recipient
	for i, line := range splitLines(contents) {
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		// Valid but unsupported SSH keys are ignored with a warning.
		if pub, err := parseSSHAuthorizedKey(line); err == nil && isSSHKeyLine(line) {
			if r, err := sshRecipientFromPublic(pub); err == nil {
				recipients = append(recipients, r)
				continue
			} else {
				warnf("recipients file %q: ignoring unsupported SSH key of type %q at line %d", name, pub.typ, i+1)
				continue
			}
		}
		r, err := parseRecipient(line)
		if err != nil {
			return nil, fmt.Errorf("%q: malformed recipient at line %d", name, i+1)
		}
		recipients = append(recipients, r)
	}
	if len(recipients) == 0 {
		return nil, fmt.Errorf("%q: no recipients found", name)
	}
	return recipients, nil
}

func isSSHKeyLine(line string) bool {
	fields := strings.Fields(line)
	if len(fields) < 2 {
		return false
	}
	k := fields[0]
	return strings.HasPrefix(k, "ssh-") || strings.HasPrefix(k, "ecdsa-") || strings.HasPrefix(k, "sk-")
}

func gatherRecipients() ([]Recipient, error) {
	var recipients []Recipient
	for _, s := range flagRecipients {
		r, err := parseRecipient(s)
		if err != nil {
			return nil, err
		}
		recipients = append(recipients, r)
	}
	for _, name := range flagRecipientsFile {
		rs, err := parseRecipientsFile(name)
		if err != nil {
			return nil, fmt.Errorf("failed to parse recipient file %q: %w", name, err)
		}
		recipients = append(recipients, rs...)
	}
	if flagEncrypt {
		for _, spec := range flagIdentities {
			if spec.plugin {
				id, err := newPluginIdentity(spec.value)
				if err != nil {
					return nil, fmt.Errorf("initializing %q: %w", spec.value, err)
				}
				recipients = append(recipients, id)
				continue
			}
			rs, err := recipientsFromIdentityFile(spec.value)
			if err != nil {
				return nil, err
			}
			recipients = append(recipients, rs...)
		}
	}
	return recipients, nil
}

// ----- identities -----

func sshPassphraseCallback(name string) ([]byte, error) {
	p, err := readSecret(fmt.Sprintf("Enter passphrase for %q:", name))
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase for %q: %w", name, err)
	}
	return p, nil
}

func readIdentityFileContents(name string) ([]byte, error) {
	if name == "-" {
		return readStdinOnce()
	}
	f, err := os.Open(name)
	if err != nil {
		return nil, fmt.Errorf("failed to open file: %w", err)
	}
	defer f.Close()
	b, err := io.ReadAll(f)
	if err != nil {
		return nil, fmt.Errorf("failed to read %q: failed to read identities file: %w", name, err)
	}
	return b, nil
}

func isArmoredAgeFile(contents []byte) (bool, error) {
	br := bufio.NewReader(bytes.NewReader(contents))
	br2, armored := detectArmor(br)
	if !armored {
		return false, nil
	}
	ar := newArmorReader(br2)
	buf := make([]byte, len(ageIntro))
	_, err := io.ReadFull(ar, buf)
	if err != nil {
		if strings.HasPrefix(err.Error(), "invalid armor:") {
			return false, err
		}
		return false, nil
	}
	return string(buf) == ageIntro, nil
}

func parseIdentitiesFile(name string) ([]Identity, error) {
	contents, err := readIdentityFileContents(name)
	if err != nil {
		return nil, err
	}
	ids, err := parseIdentitiesBytes(name, contents)
	if err != nil {
		return nil, err
	}
	return ids, nil
}

func parseIdentitiesBytes(name string, contents []byte) ([]Identity, error) {
	if bytes.HasPrefix(contents, []byte(ageIntro)) {
		return []Identity{newEncryptedIdentityFile(name, contents)}, nil
	}
	armored, err := isArmoredAgeFile(contents)
	if err != nil {
		return nil, fmt.Errorf("failed to read %q: %w", name, err)
	}
	if armored {
		return []Identity{newEncryptedIdentityFile(name, contents)}, nil
	}
	if bytes.HasPrefix(contents, []byte("-----BEGIN")) {
		id, err := parseSSHIdentityFile(name, contents, sshPassphraseCallback)
		if err != nil {
			return nil, err
		}
		return []Identity{id}, nil
	}
	var ids []Identity
	for i, line := range splitLines(contents) {
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		var id Identity
		var err error
		switch {
		case strings.HasPrefix(line, "AGE-SECRET-KEY-PQ-1"):
			var v *PQIdentity
			v, err = parsePQIdentity(line)
			if err != nil {
				return nil, fmt.Errorf("failed to read %q: error at line %d: malformed secret key: %w", name, i+1, err)
			}
			id = v
		case strings.HasPrefix(line, "AGE-SECRET-KEY-1"):
			var v *X25519Identity
			v, err = parseX25519Identity(line)
			if err != nil {
				return nil, fmt.Errorf("failed to read %q: error at line %d: malformed secret key: %w", name, i+1, err)
			}
			id = v
		case strings.HasPrefix(line, "AGE-PLUGIN-"):
			var v *pluginIdentity
			v, err = parsePluginIdentity(line)
			if err != nil {
				return nil, fmt.Errorf("failed to read %q: error at line %d: malformed plugin identity: %w", name, i+1, err)
			}
			id = v
		case strings.HasPrefix(line, "age1"):
			return nil, fmt.Errorf("failed to read %q: error at line %d: apparent recipient found in identities file", name, i+1)
		default:
			return nil, fmt.Errorf("failed to read %q: error at line %d: unknown identity type", name, i+1)
		}
		ids = append(ids, id)
	}
	if len(ids) == 0 {
		return nil, fmt.Errorf("failed to read %q: no identities found", name)
	}
	return ids, nil
}

type encryptedIdentityFile struct {
	name     string
	contents []byte
}

func newEncryptedIdentityFile(name string, contents []byte) *encryptedIdentityFile {
	return &encryptedIdentityFile{name: name, contents: append([]byte(nil), contents...)}
}

var errIdentityNotPassphrase = errors.New("identity file is encrypted with age but not with a passphrase")

func (e *encryptedIdentityFile) decryptContents() ([]byte, error) {
	scryptID := &ScryptIdentity{Callback: func() ([]byte, error) {
		return readPassphrase(fmt.Sprintf("Enter passphrase for identity file %q:", e.name))
	}}
	res, err := ageDecrypt(bytes.NewReader(e.contents), []Identity{scryptID})
	if err != nil {
		if errors.Is(err, errNoIdentityMatch) {
			if res != nil {
				for _, s := range res.Stanzas {
					if s.Type == "scrypt" {
						return nil, fmt.Errorf("failed to decrypt identity file: %w", err)
					}
				}
			}
			return nil, errIdentityNotPassphrase
		}
		return nil, fmt.Errorf("failed to decrypt identity file: %w", err)
	}
	clear, err := io.ReadAll(res.Reader)
	if err != nil {
		if errors.Is(err, errStreamAuth) {
			return nil, fmt.Errorf("failed to decrypt identity file: failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		return nil, fmt.Errorf("failed to decrypt identity file: %w", err)
	}
	return clear, nil
}

func (e *encryptedIdentityFile) Unwrap(stanzas []*Stanza) ([]byte, error) {
	clear, err := e.decryptContents()
	if err != nil {
		return nil, err
	}
	ids, err := parseIdentitiesBytes(e.name, clear)
	if err != nil {
		return nil, err
	}
	for _, id := range ids {
		fk, err := id.Unwrap(stanzas)
		if err != nil {
			if errors.Is(err, errNoIdentityMatch) {
				continue
			}
			return nil, err
		}
		return fk, nil
	}
	warnf("encrypted identity file %q didn't match file's recipients", e.name)
	return nil, errNoIdentityMatch
}

func recipientsFromIdentityFile(name string) ([]Recipient, error) {
	ids, err := parseIdentitiesFile(name)
	if err != nil {
		return nil, fmt.Errorf("reading %q: %w", name, err)
	}
	var out []Recipient
	for _, id := range ids {
		if enc, ok := id.(*encryptedIdentityFile); ok {
			clear, err := enc.decryptContents()
			if err != nil {
				return nil, fmt.Errorf("internal error processing %q: %w", name, err)
			}
			inner, err := parseIdentitiesBytes(name, clear)
			if err != nil {
				return nil, fmt.Errorf("internal error processing %q: %w", name, err)
			}
			for _, inID := range inner {
				rs, err := identityToRecipients(inID)
				if err != nil {
					return nil, fmt.Errorf("internal error processing %q: %w", name, err)
				}
				out = append(out, rs...)
			}
			continue
		}
		rs, err := identityToRecipients(id)
		if err != nil {
			return nil, fmt.Errorf("reading %q: %w", name, err)
		}
		out = append(out, rs...)
	}
	return out, nil
}

func identityToRecipients(id Identity) ([]Recipient, error) {
	switch v := id.(type) {
	case *X25519Identity:
		r, err := v.Recipient()
		if err != nil {
			return nil, err
		}
		return []Recipient{r}, nil
	case *PQIdentity:
		return []Recipient{v.recip}, nil
	case *SSHRSAIdentity:
		return []Recipient{&SSHRSARecipient{pub: v.pub}}, nil
	case *SSHEd25519Identity:
		return []Recipient{&SSHEd25519Recipient{pub: v.pub}}, nil
	case *EncryptedSSHIdentity:
		r, err := sshRecipientFromPublic(v.pub)
		if err != nil {
			return nil, err
		}
		return []Recipient{r}, nil
	case *pluginIdentity:
		return []Recipient{v}, nil
	case *encryptedIdentityFile:
		// Recursively handled by the caller normally; handle here as well.
		clear, err := v.decryptContents()
		if err != nil {
			return nil, err
		}
		inner, err := parseIdentitiesBytes(v.name, clear)
		if err != nil {
			return nil, err
		}
		var out []Recipient
		for _, inID := range inner {
			rs, err := identityToRecipients(inID)
			if err != nil {
				return nil, err
			}
			out = append(out, rs...)
		}
		return out, nil
	default:
		return nil, fmt.Errorf("unsupported identity type: %T", id)
	}
}

func gatherIdentities() ([]Identity, error) {
	if len(flagIdentities) == 0 {
		return []Identity{&ScryptIdentity{Callback: func() ([]byte, error) {
			return readPassphrase("Enter passphrase:")
		}}}, nil
	}
	var ids []Identity
	for _, spec := range flagIdentities {
		if spec.plugin {
			id, err := newPluginIdentity(spec.value)
			if err != nil {
				return nil, fmt.Errorf("initializing %q: %w", spec.value, err)
			}
			ids = append(ids, id)
			continue
		}
		fileIDs, err := parseIdentitiesFile(spec.value)
		if err != nil {
			return nil, fmt.Errorf("reading %q: %w", spec.value, err)
		}
		ids = append(ids, fileIDs...)
	}
	return ids, nil
}

// ----- encrypt / decrypt -----

func encryptPassphrase() ([]byte, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: %w", err)
	}
	defer tty.Close()
	p1, err := tty.readSecret("Enter passphrase (leave empty to autogenerate a secure one):")
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: %w", err)
	}
	if len(p1) == 0 {
		generated := generatePassphrase()
		fmt.Fprintf(tty.f, "age: using autogenerated passphrase %q\n", generated)
		return []byte(generated), nil
	}
	p2, err := tty.readSecret("Confirm passphrase:")
	if err != nil {
		return nil, fmt.Errorf("could not read passphrase: %w", err)
	}
	if !bytes.Equal(p1, p2) {
		return nil, userErr("passphrases didn't match")
	}
	return p1, nil
}

func encryptFile(in *inputFile, out *outputWriter) error {
	var recipients []Recipient
	if flagPassphrase {
		pass, err := encryptPassphrase()
		if err != nil {
			return err
		}
		recipients = []Recipient{&ScryptRecipient{passphrase: pass, LogN: 18}}
	} else {
		rs, err := gatherRecipients()
		if err != nil {
			return err
		}
		recipients = rs
	}
	var w io.Writer = out
	var aw *armorWriter
	if flagArmor {
		aw = newArmorWriter(out)
		w = aw
	}
	ew, err := ageEncrypt(w, recipients)
	if err != nil {
		var lme *labelsMismatchError
		if errors.As(err, &lme) {
			isPQ := func(l []string) bool { return len(l) == 1 && l[0] == "postquantum" }
			if (len(lme.first) == 0 && isPQ(lme.second)) || (len(lme.second) == 0 && isPQ(lme.first)) {
				return userErr("incompatible recipients: can't mix post-quantum and classic recipients, or the file would be vulnerable to quantum computers")
			}
		}
		return err
	}
	if _, err := io.Copy(ew, in.r); err != nil {
		return err
	}
	if err := ew.Close(); err != nil {
		return err
	}
	if aw != nil {
		if err := aw.Close(); err != nil {
			return err
		}
	}
	return out.Close()
}

func decryptFile(in *inputFile, out *outputWriter) error {
	identities, err := gatherIdentities()
	if err != nil {
		return err
	}
	res, err := ageDecrypt(in.r, identities)
	if err != nil {
		if errors.Is(err, errNoIdentityMatch) {
			if len(flagIdentities) == 0 {
				return userErr("the file is not passphrase-encrypted, identities are required", "specify identities with -i/--identity or -j to decrypt this file")
			}
			if res != nil {
				hasScrypt := false
				for _, s := range res.Stanzas {
					if s.Type == "scrypt" {
						hasScrypt = true
					}
				}
				if hasScrypt {
					return userErr("file is passphrase-encrypted but identities were specified with -i/--identity or -j", "remove all -i/--identity/-j flags to decrypt passphrase-encrypted files")
				}
			}
		}
		return err
	}
	_, copyErr := io.Copy(out, res.Reader)
	closeErr := out.Close()
	if copyErr != nil {
		if errors.Is(copyErr, errStreamAuth) {
			return userErr("failed to decrypt and authenticate payload chunk, file may be corrupted or tampered with")
		}
		return copyErr
	}
	return closeErr
}
