#!/usr/bin/env python3
import sys,os,base64
scenario=os.environ.get('PLUGIN_SCENARIO','plain')
log=open('/tmp/probe/plugin.log','ab',buffering=0)
def L(x):log.write((str(x)+'\n').encode())
def read_stanza():
    line=sys.stdin.buffer.readline();L(f'IN {line!r}')
    if not line:return None
    hdr=line.rstrip(b'\n');body=[]
    while True:
        line=sys.stdin.buffer.readline();L(f'INB {line!r}')
