elif scenario=='public':
    send('-> request-public\n'+base64.b64encode(b'Enter name:').decode().rstrip('=')+'\n');L(f"resp {read_stanza()}")
elif scenario=='unknown':
    send('-> frobnicate\n\n');L(f"resp {read_stanza()}")
elif scenario=='labelsPQ':
    send('-> labels postquantum\n\n');L(f"resp {read_stanza()}")
elif scenario=='error':
    send('-> error\n'+base64.b64encode(b'plugin failed badly').decode().rstrip('=')+'\n-> done\n\n')
    while read_stanza():pass
    sys.exit(0)
elif scenario=='garbage':
    send('garbage\n');sys.exit(0)
elif scenario=='exit3':
    sys.stderr.write('plugin stderr\n');sys.exit(3)
elif scenario=='norecipient':
    send('-> done\n\n')
    while read_stanza():pass
    sys.exit(0)
if '--age-plugin=recipient-v1' in sys.argv:
    send(f'-> recipient-stanza 0 example testarg\n{fk}\n-> done\n\n')
else:
    send(f'-> file-key 0\n{body}\n-> done\n\n')
while True:
    st=read_stanza();L(f'after {st}')
    if not st:break
EOS
