 pathlib.Path('/tmp/probe/plugin.log').write_bytes(b'')
 return subprocess.run([bin]+args,input=inp,capture_output=True,env=env,timeout=10)
def comp(name,args,scenario,inp=b'hello\n',stdout=False):
 try:a=run(ORIG,args,scenario,inp)
 except Exception as e:a=e
 try:b=run(NEW,args,scenario,inp)
 except Exception as e:b=e
 if isinstance(a,Exception) or isinstance(b,Exception):print('EXC',name,a,b);fails.append(name);return
 ok=a.returncode==b.returncode and a.stderr==b.stderr and (not stdout or a.stdout==b.stdout)
 print(('PASS' if ok else 'FAIL'),name,scenario,args)
 if not ok:fails.append(name);print('orig',a.returncode,a.stdout[:200],a.stderr);print('new',b.returncode,b.stdout[:200],b.stderr);print('newlog',pathlib.Path('/tmp/probe/plugin.log').read_bytes()[:2000])
for sc in ['plain','msg','secret','public','unknown','labelsPQ','error','garbage','exit3','norecipient']:
 comp('enc recip', ['-r','age1example1dpjkcmr0jjc670','/tmp/probe/plain.txt'],sc,inp=None)
 comp('enc -j', ['-e','-j','example','/tmp/probe/plain.txt'],sc,inp=None)
 comp('enc identity file',['-e','-i','/tmp/probe/plugin_id.txt','/tmp/probe/plain.txt'],sc,inp=None)
# identity decrypt of a plugin file generated by original in plain scenario
