for sc in ['plain','msg','secret','public','unknown','error','garbage','exit3','norecipient']:
 comp('dec identity file',['-d','-i','/tmp/probe/plugin_id.txt','/tmp/probe/pluginfile.age'],sc,inp=None)
 comp('dec -j',['-d','-j','example','/tmp/probe/pluginfile.age'],sc,inp=None)
# AGEDEBUG compare normalized for random grease/filekey? Just new vs org pattern not exact impossible due random. Skip
print('fails',fails)
