new='''type lineBreakWriter struct {
	w   io.Writer
	col int
}

func (lw *lineBreakWriter) Write(p []byte) (int, error) {
	written := 0
	for _, b := range p {
		if lw.col == 64 {
			if _, err := lw.w.Write([]byte("\\n")); err != nil {
				return written, err
			}
			lw.col = 0
		}
		if _, err := lw.w.Write([]byte{b}); err != nil {
			return written, err
		}
		lw.col++
		written++
	}
	return written, nil
}

type armorWriter struct {
	w           io.Writer
	line        *lineBreakWriter
	enc         io.WriteCloser
	wroteHeader bool
	closed      bool
}

func newArmorWriter(w io.Writer) *armorWriter { return &armorWriter{w: w} }

func (aw *armorWriter) init() error {
	if aw.wroteHeader {
		return nil
	}
	if _, err := io.WriteString(aw.w, armorBegin+"\\n"); err != nil {
		return err
	}
	aw.wroteHeader = true
	aw.line = &lineBreakWriter{w: aw.w}
	aw.enc = base64.NewEncoder(base64.StdEncoding, aw.line)
	return nil
}

func (aw *armorWriter) Write(p []byte) (int, error) {
	if err := aw.init(); err != nil {
		return 0, err
	}
	return aw.enc.Write(p)
}

func (aw *armorWriter) Close() error {
	if aw.closed {
		return nil
	}
	aw.closed = true
	if err := aw.init(); err != nil {
		return err
	}
	if err := aw.enc.Close(); err != nil {
		return err
	}
	if aw.line.col > 0 {
		if _, err := io.WriteString(aw.w, "\\n"); err != nil {
			return err
		}
	}
	_, err := io.WriteString(aw.w, armorEnd+"\\n")
	return err
}
