 hdr,b=st
 if hdr.startswith(b'-> wrap-file-key'):fk=b''.join(b).decode()
 if hdr==b'-> done':break
send('-> recipient-stanza 1 example x\n'+fk+'\n')
L(f'response malformed {read_stanza()}')
send(f'-> recipient-stanza 0 example x\n{fk}\n-> done\n\n')
while True:
 st=read_stanza();L(f'after {st}')
 if not st:break
