 labels:=[][]byte{[]byte("age-encryption.org/v1/mlkem768x25519"),[]byte("mlkem768x25519"),[]byte("")}
 salts:=[]struct{name string;get func(map[string]string)[]byte}{{"enc+pk",func(s map[string]string)[]byte{return append(append([]byte{},hx6(s["enc"])...),pk...)}},{"empty",func(map[string]string)[]byte{return nil}},{"enc",func(s map[string]string)[]byte{return hx6(s["enc"])}},{"pk",func(map[string]string)[]byte{return pk}}}
 for _,secname:=range []string{"ssM+dh","dh+ssM","xwing","ssM","dh"}{
