        ct:=hx6(s["wrapped"]);var good bool;if aead==3{_,e:=chachaPoly1305Open(key,nonce,ct,nil);good=e==nil}else{b,e:=aes.NewCipher(key);if e==nil{g,e:=cipher.NewGCM(b);if e==nil{_,e=g.Open(nil,nonce,ct,nil);good=e==nil}}}
        if !good{ok=false;break}
       }
       if ok{t.Logf("MATCH sec=%s salt=%s info=%q outlen=%d split=%d aead=%d",secname,salt.name,info,outlen,split,aead);return}
      }
     }
    }
   }
  }
 }
}
EOF
