package main
import("encoding/binary";"encoding/hex";"encoding/json";"os";"testing";"crypto/sha256")
func hx9(s string)[]byte{b,_:=hex.DecodeString(s);return b}
func lext9(suite,salt []byte,label string,ikm []byte)[]byte{li:=append([]byte("HPKE-v1"),suite...);li=append(li,label...);li=append(li,ikm...);return hkdfExtract(sha256.New,salt,li)}
func lexp9(suite,prk []byte,label string,info []byte,L int)[]byte{li:=make([]byte,2);binary.BigEndian.PutUint16(li,uint16(L));li=append(li,[]byte("HPKE-v1")...);li=append(li,suite...);li=append(li,label...);li=append(li,info...);return hkdfExpand(sha256.New,prk,li,L)}
func TestXWingLabelBrute(t *testing.T){
 data,_:=os.ReadFile("/tmp/probe/pq_samples.json");var in struct{PkX string;Samples []map[string]string};json.Unmarshal(data,&in);pkX:=hx9(in.PkX)
 alphabet:=[]byte{'\\','.','^','/','-','_'}
 infos:=[][]byte{[]byte("age-encryption.org/v1/mlkem768x25519"),[]byte("")}
 var gen func(cur []byte,depth int)
 found:=false
 gen=func(cur []byte,depth int){
  if found{return}
  if depth>=4{
   for _,info:=range infos{
    ok:=true
    for _,s:=range in.Samples{
      ss:=sha3_256(append(append(append(append(append([]byte{},hx9(s["ssM"])...),hx9(s["dhX"])...),hx9(s["eph"])...),pkX...),cur...))
      suite:=[]byte{'H','P','K','E',0x64,0x7a,0,1,0,3};pskh:=lext9(suite,nil,"psk_id_hash",nil);ih:=lext9(suite,nil,"info_hash",info);ctx:=append([]byte{0},append(pskh,ih...)...);sec:=lext9(suite,ss,"secret",nil);key:=lexp9(suite,sec,"key",ctx,32);nonce:=lexp9(suite,sec,"base_nonce",ctx,12)
      if _,err:=chachaPoly1305Open(key,nonce,hx9(s["wrapped"]),nil);err!=nil{ok=false;break}
    }
    if ok{t.Logf("MATCH label=%q info=%q",cur,info);found=true;return}
   }
  }
  if depth==6{return}
  for _,c:=range alphabet{gen(append(cur,c),depth+1);if found{return}}
 }
 gen(nil,0)
}
EOF
go test -run TestXWingLabelBrute -v -timeout 170s ./... 2>&1 | tail -n 20; rm -f xwing_label_test.go"}

